python3 - <<'PY'
import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))
def shape(s,depth=0):
 if not s:return '?'
 if '$ref' in s:return s['$ref'].split('/')[-1]
 t=s.get('type','')
 if t=='object' or 'properties' in s:
  req=set(s.get('required',[])); parts=[]
  for k,v in s.get('properties',{}).items(): parts.append(k+('*' if k in req else '')+':'+shape(v,depth+1))
  return '{'+','.join(parts)+'}'
 if t=='array':return '['+shape(s.get('items',{}),depth+1)+']'
 if 'enum' in s:return 'enum('+ '|'.join(map(str,s['enum'])) +')'
 return t+(('/'+s['format']) if s.get('format') else '')
with open('/tmp/api-summary.txt','w') as out:
 for p,item in D['paths'].items():
  for m,op in item.items():
   if m.startswith('x-'):continue
   out.write(f"\n### {m.upper()} {p} [{op['operationId']}]\n")
   for prm in op.get('parameters',[]):
    out.write('PARAM '+prm['in']+' '+prm['name']+('*' if prm.get('required') else '')+':'+shape(prm.get('schema',{}))+'\n')
   rb=op.get('requestBody')
   if rb:
    out.write('BODY'+('*' if rb.get('required') else '')+' '+shape(rb.get('content',{}).get('application/json',{}).get('schema',{}))+'\n')
   for status,res in op['responses'].items():
    ct=res.get('content',{})
    sch=(ct.get('application/json') or ct.get('text/event-stream') or {}).get('schema',{})
    out.write(status+' '+shape(sch)+'\n')
PY
sed -n '1,240p' /tmp/api-summary.txt

