import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))
def shape(s):
 if '$ref' in s:return s['$ref'].split('/')[-1]
 if s.get('type')=='array':return '['+shape(s.get('items',{}))+']'
 if 'enum' in s:return 'enum('+ '|'.join(map(str,s['enum'])) +')'
 if s.get('type')=='object' or 'properties' in s:
  req=set(s.get('required',[])); return '{'+','.join(k+('*' if k in req else '')+':'+shape(v) for k,v in s.get('properties',{}).items())+'}'
 return s.get('type','any')+(('/'+s['format']) if s.get('format') else '')
for n,s in D['components']['schemas'].items():print(n,'=',shape(s))
