package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"golang.org/x/crypto/bcrypt"
)

type Certification struct { Code string `json:"code"`; Active bool `json:"active"`; ExpiresAt string `json:"expiresAt,omitempty"` }
type createUserRequest struct { Username string `json:"username"`; InitialPassword string `json:"initialPassword"`; Email string `json:"email,omitempty"`; FullName string `json:"fullName,omitempty"`; Phone string `json:"phone,omitempty"`; Roles []string `json:"roles"`; Qualifications []string `json:"qualifications,omitempty"`; Certifications []Certification `json:"certifications,omitempty"`; Active bool `json:"active"`; AssignedLocationID string `json:"assignedLocationId,omitempty"` }
type updateUserRequest struct { UserID string `json:"userId"`; Roles []string `json:"roles"`; Qualifications []string `json:"qualifications,omitempty"`; Certifications []Certification `json:"certifications,omitempty"`; Active bool `json:"active"`; AssignedLocationID string `json:"assignedLocationId,omitempty"` }
var validRoles=[]string{"administrator","dispatcher","requester","collection_professional","delivery_partner","node_handler","laboratory_team"}

func validRoleSet(rs []string)bool{if len(rs)==0{return false};for _,r:=range rs{if !contains(validRoles,r){return false}};return true}
func validCerts(cs []Certification)bool{for _,c:=range cs{if c.Code==""{return false};if c.ExpiresAt!=""{if _,e:=time.Parse(time.RFC3339,c.ExpiresAt);e!=nil{return false}}};return true}
func userResponse(id string,in createUserRequest)map[string]any{ cs:=in.Certifications;if cs==nil{cs=[]Certification{}};qs:=in.Qualifications;if qs==nil{qs=[]string{}};m:=map[string]any{"userId":id,"username":in.Username,"roles":in.Roles,"qualifications":qs,"certifications":cs,"active":in.Active};if in.Email!=""{m["email"]=in.Email};if in.FullName!=""{m["fullName"]=in.FullName};if in.Phone!=""{m["phone"]=in.Phone};return m }
