func (a *App) createLocation(w http.ResponseWriter,r *http.Request,update bool)error{u,e:=requireRole(r,"administrator");if e!=nil{return e};var in locationRequest;if e=decode(r,&in);e!=nil{return e};if !validCoordinate(in.Coordinate){return fail(400,"invalid_coordinate","invalid coordinate")};if in.CoverageKm<0{return fail(400,"invalid_node_coverage","coverage cannot be negative")};if in.HandlingMinutes<0{return fail(400,"invalid_handling_time","handling time cannot be negative")};states:=functionMap(in.Functions);for _,f:=range in.Functions{if _,ok:=states[f];!ok{return fail(400,"invalid_location_function","invalid location function")}};raw,_:=json.Marshal(states);id:=in.LocationID;if update{res,x:=a.db.ExecContext(r.Context(),`UPDATE lablogistics.locations SET name=$2,latitude=$3,longitude=$4,coverage_km=$5,handling_minutes=$6,functions=$7 WHERE id=$1`,id,in.Name,in.Coordinate.Latitude,in.Coordinate.Longitude,in.CoverageKm,in.HandlingMinutes,raw);e=x;if e==nil{n,_:=res.RowsAffected();if n==0{return fail(404,"not_found","location not found")}};var active bool;if e==nil{e=a.db.QueryRowContext(r.Context(),`SELECT active FROM lablogistics.locations WHERE id=$1`,id).Scan(&active);in.Active=active}}else{id=uuid();_,e=a.db.ExecContext(r.Context(),`INSERT INTO lablogistics.locations(id,name,latitude,longitude,coverage_km,handling_minutes,active,functions)VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,id,in.Name,in.Coordinate.Latitude,in.Coordinate.Longitude,in.CoverageKm,in.HandlingMinutes,in.Active,raw)};if e!=nil{return e};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,map[bool]string{true:"update_location",false:"create_location"}[update],"location",id,true,map[string]any{});writeJSON(w,201,map[string]any{"data":locationMap(id,in,states)});return nil}

type connectionRequest struct{FromLocationID string `json:"fromLocationId"`;ToLocationID string `json:"toLocationId"`;TravelMinutes int `json:"travelMinutes"`;CostUnits float64 `json:"costUnits"`;Cooled bool `json:"cooled"`;Active bool `json:"active"`}
func (a *App) createConnection(w http.ResponseWriter,r *http.Request)error{u,e:=requireRole(r,"administrator");if e!=nil{return e};var in connectionRequest;if e=decode(r,&in);e!=nil{return e};if in.FromLocationID==in.ToLocationID||in.TravelMinutes<=0{return fail(400,"invalid_connection","invalid connection")};id:=uuid();_,e=a.db.ExecContext(r.Context(),`INSERT INTO lablogistics.connections(id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active)VALUES($1,$2,$3,$4,$5,$6,$7)`,id,in.FromLocationID,in.ToLocationID,in.TravelMinutes,in.CostUnits,in.Cooled,in.Active);if e!=nil{return e};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"create_connection","connection",id,true,map[string]any{});writeJSON(w,201,map[string]any{"data":map[string]any{"connectionId":id,"fromLocationId":in.FromLocationID,"toLocationId":in.ToLocationID,"travelMinutes":in.TravelMinutes,"costUnits":in.CostUnits,"cooled":in.Cooled,"active":in.Active}});return nil}

type statusRequest struct{LocationID string `json:"locationId"`;Active bool `json:"active"`}
func (a *App) setLocationStatus(w http.ResponseWriter,r *http.Request)error{u,e:=requireRole(r,"administrator");if e!=nil{return e};var in statusRequest;if e=decode(r,&in);e!=nil{return e};res,e:=a.db.ExecContext(r.Context(),`UPDATE lablogistics.locations SET active=$2 WHERE id=$1`,in.LocationID,in.Active);if e!=nil{return e};n,_:=res.RowsAffected();if n==0{return fail(404,"not_found","location not found")};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"set_location_status","location",in.LocationID,true,map[string]any{"active":in.Active});writeJSON(w,200,map[string]any{"data":map[string]any{"locationId":in.LocationID,"active":in.Active}});return nil}
type functionStatusRequest struct{LocationID string `json:"locationId"`;Function string `json:"function"`;Active bool `json:"active"`}
func (a *App) setLocationFunctionStatus(w http.ResponseWriter,r *http.Request)error{u,e:=requireRole(r,"administrator");if e!=nil{return e};var in functionStatusRequest;if e=decode(r,&in);e!=nil{return e};if _,ok:=functionMap(nil)[in.Function];!ok{return fail(400,"invalid_location_function","invalid location function")};var raw []byte;e=a.db.QueryRowContext(r.Context(),`SELECT functions FROM lablogistics.locations WHERE id=$1`,in.LocationID).Scan(&raw);if e==sql.ErrNoRows{return fail(404,"not_found","location not found")};var states map[string]bool;_=json.Unmarshal(raw,&states);states[in.Function]=in.Active;b,_:=json.Marshal(states);_,e=a.db.ExecContext(r.Context(),`UPDATE lablogistics.locations SET functions=$2 WHERE id=$1`,in.LocationID,b);if e!=nil{return e};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"set_location_function_status","location",in.LocationID,true,map[string]any{"function":in.Function,"active":in.Active});writeJSON(w,200,map[string]any{"data":map[string]any{"locationId":in.LocationID,"function":in.Function,"active":in.Active,"functions":states}});return nil}
type connectionStatusRequest struct{ConnectionID string `json:"connectionId"`;Active bool `json:"active"`}
func (a *App) setConnectionStatus(w http.ResponseWriter,r *http.Request)error{u,e:=requireRole(r,"administrator");if e!=nil{return e};var in connectionStatusRequest;if e=decode(r,&in);e!=nil{return e};res,e:=a.db.ExecContext(r.Context(),`UPDATE lablogistics.connections SET active=$2 WHERE id=$1`,in.ConnectionID,in.Active);if e!=nil{return e};n,_:=res.RowsAffected();if n==0{return fail(404,"not_found","connection not found")};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"set_connection_status","connection",in.ConnectionID,true,map[string]any{"active":in.Active});writeJSON(w,200,map[string]any{"data":map[string]any{"connectionId":in.ConnectionID,"active":in.Active}});return nil}

type capacityRequest struct{ResourceID string `json:"resourceId"`;CapacityUnits int `json:"capacityUnits"`;CooledCapacityUnits int `json:"cooledCapacityUnits,omitempty"`}
func (a *App) configureCapacity(w http.ResponseWriter,r *http.Request)error{u:=currentUser(r);if u.ActiveRole==""{return fail(409,"role_not_selected","select an active role")};if u.ActiveRole!="administrator"&&!((u.ActiveRole=="node_handler"||u.ActiveRole=="laboratory_team")&&u.AssignedLocationID!="" ){return fail(403,"forbidden","cannot configure capacity")};var in capacityRequest;if e:=decode(r,&in);e!=nil{return e};if in.CapacityUnits<0||in.CooledCapacityUnits<0{return fail(400,"invalid_capacity","capacity cannot be negative")};if u.ActiveRole!="administrator"&&u.AssignedLocationID!=in.ResourceID{return fail(403,"forbidden","capacity is outside assigned location")};res,e:=a.db.ExecContext(r.Context(),`UPDATE lablogistics.locations SET capacity_units=$2,cooled_capacity_units=$3 WHERE id=$1 AND reserved_units<=$2 AND cooled_reserved_units<=$3`,in.ResourceID,in.CapacityUnits,in.CooledCapacityUnits);if e!=nil{return e};n,_:=res.RowsAffected();if n==0{res,e=a.db.ExecContext(r.Context(),`UPDATE lablogistics.connections SET capacity_units=$2,cooled_capacity_units=$3 WHERE id=$1 AND reserved_units<=$2 AND cooled_reserved_units<=$3`,in.ResourceID,in.CapacityUnits,in.CooledCapacityUnits);if e!=nil{return e};n,_=res.RowsAffected()};if n==0{return fail(409,"capacity_reserved","capacity is below current reservations")};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"configure_capacity","resource",in.ResourceID,true,map[string]any{"capacityUnits":in.CapacityUnits,"cooledCapacityUnits":in.CooledCapacityUnits});writeJSON(w,200,map[string]any{"data":map[string]any{"resourceId":in.ResourceID,"capacityUnits":in.CapacityUnits,"cooledCapacityUnits":in.CooledCapacityUnits}});return nil}
type acceptanceRequest struct{LaboratoryID string `json:"laboratoryId"`;SampleTypeID string `json:"sampleTypeId"`;Accepts bool `json:"accepts"`}
func (a *App) configureAcceptance(w http.ResponseWriter,r *http.Request)error{u,e:=requireRole(r,"administrator");if e!=nil{return e};var in acceptanceRequest;if e=decode(r,&in);e!=nil{return e};id:=uuid();e=a.db.QueryRowContext(r.Context(),`INSERT INTO lablogistics.laboratory_acceptance(id,laboratory_id,sample_type_id,accepts)VALUES($1,$2,$3,$4) ON CONFLICT(laboratory_id,sample_type_id)DO UPDATE SET accepts=excluded.accepts RETURNING id`,id,in.LaboratoryID,in.SampleTypeID,in.Accepts).Scan(&id);if e!=nil{return e};_=a.bumpNetwork(r.Context());_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"configure_laboratory_acceptance","location",in.LaboratoryID,true,map[string]any{"sampleTypeId":in.SampleTypeID,"accepts":in.Accepts});writeJSON(w,200,map[string]any{"data":map[string]any{"acceptanceId":id,"accepts":in.Accepts}});return nil}
type availabilityRequest struct{WorkerID string `json:"workerId"`;Available bool `json:"available"`;CapacityUnits int `json:"capacityUnits"`}
func (a *App) setWorkerAvailability(w http.ResponseWriter,r *http.Request)error{u:=currentUser(r);if u.ActiveRole==""{return fail(409,"role_not_selected","select an active role")};var in availabilityRequest;if e:=decode(r,&in);e!=nil{return e};if in.CapacityUnits<0{return fail(400,"invalid_capacity","capacity cannot be negative")};if u.ID!=in.WorkerID&&u.ActiveRole!="administrator"&&u.ActiveRole!="dispatcher"{return fail(403,"forbidden","cannot update another worker")};res,e:=a.db.ExecContext(r.Context(),`UPDATE lablogistics.users SET available=$2,capacity_units=$3 WHERE id=$1`,in.WorkerID,in.Available,in.CapacityUnits);if e!=nil{return e};n,_:=res.RowsAffected();if n==0{return fail(404,"not_found","worker not found")};_=a.audit(r.Context(),nil,u.ID,u.ActiveRole,"set_worker_availability","user",in.WorkerID,true,map[string]any{"available":in.Available});writeJSON(w,200,map[string]any{"data":map[string]any{"workerId":in.WorkerID,"available":in.Available,"capacityUnits":in.CapacityUnits}});return nil}
func (a *App)bumpNetwork(ctx context.Context)error{_,e:=a.db.ExecContext(ctx,`UPDATE lablogistics.serviceability_snapshot SET version=version+1,network_revision=network_revision+1,computed_at=now()`);return e}
func isUnique(e error)bool{return e!=nil&&strings.Contains(e.Error(),"duplicate key")}

