func (a *App) requesterSamples(ctx context.Context,userID string)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,request_id,status,serviceability,requested_at,delivery_deadline,earliest_collection_at,latest_collection_at,coalesce(active_journey_id::text,''),coalesce(target_laboratory_id::text,''),coalesce(current_holder_id::text,''),requester_id,location_recorded_at FROM lablogistics.samples WHERE requester_id=$1 ORDER BY created_at DESC`,userID);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,rid,status,svc,jid,lab,holder,requester string;var requested,deadline,earliest,latest time.Time;var loc sql.NullTime;if e=rows.Scan(&id,&rid,&status,&svc,&requested,&deadline,&earliest,&latest,&jid,&lab,&holder,&requester,&loc);e!=nil{return nil,e};hist,e:=a.timeline(ctx,"sample",id);if e!=nil{return nil,e};m:=map[string]any{"kind":"sample","sampleId":id,"requestId":rid,"status":status,"serviceability":svc,"requestedAt":requested.UTC().Format(time.RFC3339Nano),"deliveryDeadline":deadline.UTC().Format(time.RFC3339Nano),"earliestCollectionAt":earliest.UTC().Format(time.RFC3339Nano),"latestCollectionAt":latest.UTC().Format(time.RFC3339Nano),"requesterId":requester,"history":hist,"locationStale":locationStale(loc)};if jid!=""{m["activeJourneyId"]=jid;m["journeyId"]=jid};if lab!=""{m["laboratoryId"]=lab};if holder!=""{m["currentHolderId"]=holder};if loc.Valid{m["locationRecordedAt"]=loc.Time.UTC().Format(time.RFC3339Nano)};out=append(out,m)};return out,rows.Err()}
func (a *App) journeyWork(ctx context.Context)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,status,route_mode,plan_version,sample_ids,estimated_delivery_at,(SELECT count(*) FROM lablogistics.assignments a WHERE a.journey_id=j.id) FROM lablogistics.journeys j ORDER BY created_at DESC`);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,status,mode string;var version,count int;var samples []string;var eta sql.NullTime;if e=rows.Scan(&id,&status,&mode,&version,&samples,&eta,&count);e!=nil{return nil,e};hist,e:=a.timeline(ctx,"journey",id);if e!=nil{return nil,e};m:=map[string]any{"kind":"journey","journeyId":id,"status":status,"routeMode":mode,"planVersion":version,"sampleIds":samples,"estimatedDeliveryAt":time.Now().UTC().Format(time.RFC3339Nano),"assignmentCount":count,"history":hist};if eta.Valid{m["estimatedDeliveryAt"]=eta.Time.UTC().Format(time.RFC3339Nano)};out=append(out,m)};return out,rows.Err()}
func (a *App) assignmentWork(ctx context.Context,u *User)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,sample_id,status,kind,journey_id,coalesce(from_location_id::text,''),coalesce(to_location_id::text,''),sequence,offer_expires_at,coalesce(node_id::text,''),coalesce(laboratory_id::text,'') FROM lablogistics.assignments WHERE (offered_to=$1 OR worker_id=$1) AND required_role=$2 ORDER BY created_at DESC`,u.ID,u.ActiveRole);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,sid,status,kind,jid,from,to,node,lab string;var seq int;var expires sql.NullTime;if e=rows.Scan(&id,&sid,&status,&kind,&jid,&from,&to,&seq,&expires,&node,&lab);e!=nil{return nil,e};hist,e:=a.timeline(ctx,"assignment",id);if e!=nil{return nil,e};m:=map[string]any{"kind":kind,"assignmentId":id,"sampleId":sid,"status":status,"journeyId":jid,"sequence":seq,"history":hist};if from!=""{m["fromLocationId"]=from};if to!=""{m["toLocationId"]=to};if node!=""{m["nodeId"]=node};if lab!=""{m["laboratoryId"]=lab};if expires.Valid{m["offerExpiresAt"]=expires.Time.UTC().Format(time.RFC3339Nano)};if node!=""||lab!=""{resource:=node;if resource==""{resource=lab};if cap,e:=a.capacity(ctx,resource);e==nil{m["destinationCapacity"]=cap}};out=append(out,m)};return out,rows.Err()}
func locationStale(t sql.NullTime)bool{return !t.Valid||time.Since(t.Time)>10*time.Minute}

func (a *App) timeline(ctx context.Context,entityType,entityID string)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,action,actor_id,role,entity_type,entity_id,success,occurred_at,details FROM lablogistics.audit_log WHERE entity_type=$1 AND entity_id=$2 ORDER BY occurred_at,id`,entityType,entityID);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id int;var action,actor,role,et,eid string;var success bool;var at time.Time;var raw []byte;if e=rows.Scan(&id,&action,&actor,&role,&et,&eid,&success,&at,&raw);e!=nil{return nil,e};var d map[string]any;_=json.Unmarshal(raw,&d);out=append(out,map[string]any{"eventId":id,"action":action,"actorId":actor,"role":role,"entityType":et,"entityId":eid,"success":success,"occurredAt":at.UTC().Format(time.RFC3339Nano),"details":d})};return out,rows.Err()}

func (a *App) canViewSample(ctx context.Context,u *User,sampleID string)error{if u.ActiveRole=="dispatcher"||u.ActiveRole=="administrator"{return nil};var n int;if u.ActiveRole=="requester"{e:=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogistics.samples WHERE id=$1 AND requester_id=$2`,sampleID,u.ID).Scan(&n);if e!=nil{return e}}else{e:=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogistics.assignments WHERE sample_id=$1 AND (offered_to=$2 OR worker_id=$2)`,sampleID,u.ID).Scan(&n);if e!=nil{return e}};if n==0{return fail(403,"forbidden","sample is outside selected role scope")};return nil}
