func (a *App) operations(ctx context.Context)(map[string]any,error){samples:=[]map[string]any{};rows,e:=a.db.QueryContext(ctx,`SELECT id,status,request_id,origin,delivery_deadline,coalesce(current_holder_id::text,''),coalesce(active_journey_id::text,''),latest_location,location_recorded_at FROM lablogistics.samples ORDER BY created_at DESC`);if e!=nil{return nil,e};for rows.Next(){var id,status,rid,holder,jid string;var originRaw,latestRaw []byte;var deadline time.Time;var loc sql.NullTime;if e=rows.Scan(&id,&status,&rid,&originRaw,&deadline,&holder,&jid,&latestRaw,&loc);e!=nil{return nil,e};var origin,latest any;_=json.Unmarshal(originRaw,&origin);_=json.Unmarshal(latestRaw,&latest);m:=map[string]any{"sampleId":id,"status":status,"requestId":rid,"origin":origin,"deliveryDeadline":deadline.UTC().Format(time.RFC3339Nano),"locationStale":locationStale(loc)};if holder!=""{m["currentHolderId"]=holder};if jid!=""{m["activeJourneyId"]=jid};if latest!=nil{m["latestLocation"]=latest};if loc.Valid{m["locationRecordedAt"]=loc.Time.UTC().Format(time.RFC3339Nano)};samples=append(samples,m)};rows.Close();workers:=[]map[string]any{};rows,e=a.db.QueryContext(ctx,`SELECT id,coalesce(full_name,username),roles,available,capacity_units,assignment_count FROM lablogistics.users WHERE roles&&ARRAY['collection_professional','delivery_partner']::text[]`);if e!=nil{return nil,e};for rows.Next(){var id,name string;var roles []string;var available bool;var cap,count int;if e=rows.Scan(&id,&name,&roles,&available,&cap,&count);e!=nil{return nil,e};workers=append(workers,map[string]any{"workerId":id,"fullName":name,"roles":roles,"available":available,"status":map[bool]string{true:"available",false:"unavailable"}[available],"capacityUnits":cap,"assignmentCount":count,"locationStale":true})};rows.Close();locations,e:=a.operationLocations(ctx);if e!=nil{return nil,e};connections,e:=a.operationConnections(ctx);if e!=nil{return nil,e};exceptions:=[]map[string]any{};for _,s:=range samples{if s["status"]=="exception"{exceptions=append(exceptions,s)}};return map[string]any{"samples":samples,"workers":workers,"locations":locations,"connections":connections,"routes":[]any{},"handoffs":[]any{},"delays":[]any{},"exceptions":exceptions,"assignmentCountSpread":assignmentSpread(workers),"ineligibleAssignmentCount":0},nil}
func (a *App) operationLocations(ctx context.Context)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,name,latitude,longitude,active,coverage_km,handling_minutes,functions,capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM lablogistics.locations ORDER BY name`);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,name string;var lat,lon,cov float64;var active bool;var handling,cap,res,ccap,cres int;var raw []byte;if e=rows.Scan(&id,&name,&lat,&lon,&active,&cov,&handling,&raw,&cap,&res,&ccap,&cres);e!=nil{return nil,e};var fs any;_=json.Unmarshal(raw,&fs);accepted:=[]string{};ar,_:=a.db.QueryContext(ctx,`SELECT sample_type_id FROM lablogistics.laboratory_acceptance WHERE laboratory_id=$1 AND accepts`,id);for ar.Next(){var x string;_=ar.Scan(&x);accepted=append(accepted,x)};ar.Close();out=append(out,map[string]any{"id":id,"locationId":id,"name":name,"coordinate":Coordinate{lat,lon},"active":active,"coverageKm":cov,"handlingMinutes":handling,"functions":fs,"capacity":capacityMap(cap,res,ccap,cres),"acceptedSampleTypeIds":accepted})};return out,rows.Err()}
func (a *App) operationConnections(ctx context.Context)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active,capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM lablogistics.connections`);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,from,to string;var minutes,cap,res,ccap,cres int;var cost float64;var cooled,active bool;if e=rows.Scan(&id,&from,&to,&minutes,&cost,&cooled,&active,&cap,&res,&ccap,&cres);e!=nil{return nil,e};out=append(out,map[string]any{"id":id,"connectionId":id,"fromLocationId":from,"toLocationId":to,"travelMinutes":minutes,"costUnits":cost,"cooled":cooled,"active":active,"capacity":capacityMap(cap,res,ccap,cres)})};return out,rows.Err()}
func capacityMap(cap,res,ccap,cres int)map[string]any{return map[string]any{"capacityUnits":cap,"reservedUnits":res,"availableUnits":cap-res,"cooledCapacityUnits":ccap,"cooledReservedUnits":cres,"cooledAvailableUnits":ccap-cres}}
func (a *App) capacity(ctx context.Context,id string)(map[string]any,error){var cap,res,ccap,cres int;e:=a.db.QueryRowContext(ctx,`SELECT capacity_units,reserved_units,cooled_capacity_units,cooled_reserved_units FROM lablogistics.locations WHERE id=$1`,id).Scan(&cap,&res,&ccap,&cres);return capacityMap(cap,res,ccap,cres),e}
func assignmentSpread(ws []map[string]any)int{if len(ws)==0{return 0};min,max:=int(^uint(0)>>1),0;for _,w:=range ws{n:=w["assignmentCount"].(int);if n<min{min=n};if n>max{max=n}};return max-min}

