package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"time"
)

type roleWorkRequest struct{Role string `json:"role,omitempty"`;Status string `json:"status,omitempty"`}
type idRequest struct{JourneyID string `json:"journeyId,omitempty"`;SampleID string `json:"sampleId,omitempty"`}

func (a *App) listRoleWork(w http.ResponseWriter,r *http.Request)error{u:=currentUser(r);if u.ActiveRole==""{return fail(409,"role_not_selected","select an active role")};var in roleWorkRequest;if e:=decode(r,&in);e!=nil{return e};if in.Role!=""&&in.Role!=u.ActiveRole{return fail(403,"forbidden","work must be viewed under the selected role")};out:=map[string]any{"pending":[]any{},"inProgress":[]any{},"completed":[]any{}};if u.ActiveRole=="requester"{items,e:=a.requesterSamples(r.Context(),u.ID);if e!=nil{return e};for _,x:=range items{bucket:="inProgress";s,_:=x["status"].(string);if contains([]string{"received","cancelled","expired"},s){bucket="completed"}else if s=="requested"{bucket="pending"};out[bucket]=append(out[bucket].([]any),x)}}else if u.ActiveRole=="dispatcher"||u.ActiveRole=="administrator"{items,e:=a.journeyWork(r.Context());if e!=nil{return e};for _,x:=range items{bucket:="inProgress";if contains([]string{"completed","cancelled","expired"},x["status"].(string)){bucket="completed"};out[bucket]=append(out[bucket].([]any),x)}}else{items,e:=a.assignmentWork(r.Context(),u);if e!=nil{return e};for _,x:=range items{bucket:="inProgress";s:=x["status"].(string);if s=="offered"||s=="pending"{bucket="pending"}else if s=="completed"||s=="declined"||s=="cancelled"{bucket="completed"};out[bucket]=append(out[bucket].([]any),x)}};writeJSON(w,200,map[string]any{"data":out});return nil}

func (a *App) requesterSamples(ctx context.Context,userID string)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,request_id,status,serviceability,requested_at,delivery_deadline,earliest_collection_at,latest_collection_at,coalesce(active_journey_id::text,''),coalesce(target_laboratory_id::text,''),coalesce(current_holder_id::text,''),requester_id,location_recorded_at FROM lablogistics.samples WHERE requester_id=$1 ORDER BY created_at DESC`,userID);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,rid,status,svc,jid,lab,holder,requester string;var requested,deadline,earliest,latest time.Time;var loc sql.NullTime;if e=rows.Scan(&id,&rid,&status,&svc,&requested,&deadline,&earliest,&latest,&jid,&lab,&holder,&requester,&loc);e!=nil{return nil,e};hist,e:=a.timeline(ctx,"sample",id);if e!=nil{return nil,e};m:=map[string]any{"kind":"sample","sampleId":id,"requestId":rid,"status":status,"serviceability":svc,"requestedAt":requested.UTC().Format(time.RFC3339Nano),"deliveryDeadline":deadline.UTC().Format(time.RFC3339Nano),"earliestCollectionAt":earliest.UTC().Format(time.RFC3339Nano),"latestCollectionAt":latest.UTC().Format(time.RFC3339Nano),"requesterId":requester,"history":hist,"locationStale":locationStale(loc)};if jid!=""{m["activeJourneyId"]=jid;m["journeyId"]=jid};if lab!=""{m["laboratoryId"]=lab};if holder!=""{m["currentHolderId"]=holder};if loc.Valid{m["locationRecordedAt"]=loc.Time.UTC().Format(time.RFC3339Nano)};out=append(out,m)};return out,rows.Err()}
func (a *App) journeyWork(ctx context.Context)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,status,route_mode,plan_version,sample_ids,estimated_delivery_at,(SELECT count(*) FROM lablogistics.assignments a WHERE a.journey_id=j.id) FROM lablogistics.journeys j ORDER BY created_at DESC`);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,status,mode string;var version,count int;var samples []string;var eta sql.NullTime;if e=rows.Scan(&id,&status,&mode,&version,&samples,&eta,&count);e!=nil{return nil,e};hist,e:=a.timeline(ctx,"journey",id);if e!=nil{return nil,e};m:=map[string]any{"kind":"journey","journeyId":id,"status":status,"routeMode":mode,"planVersion":version,"sampleIds":samples,"estimatedDeliveryAt":time.Now().UTC().Format(time.RFC3339Nano),"assignmentCount":count,"history":hist};if eta.Valid{m["estimatedDeliveryAt"]=eta.Time.UTC().Format(time.RFC3339Nano)};out=append(out,m)};return out,rows.Err()}
func (a *App) assignmentWork(ctx context.Context,u *User)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,sample_id,status,kind,journey_id,coalesce(from_location_id::text,''),coalesce(to_location_id::text,''),sequence,offer_expires_at,coalesce(node_id::text,''),coalesce(laboratory_id::text,'') FROM lablogistics.assignments WHERE (offered_to=$1 OR worker_id=$1) AND required_role=$2 ORDER BY created_at DESC`,u.ID,u.ActiveRole);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,sid,status,kind,jid,from,to,node,lab string;var seq int;var expires sql.NullTime;if e=rows.Scan(&id,&sid,&status,&kind,&jid,&from,&to,&seq,&expires,&node,&lab);e!=nil{return nil,e};hist,e:=a.timeline(ctx,"assignment",id);if e!=nil{return nil,e};m:=map[string]any{"kind":kind,"assignmentId":id,"sampleId":sid,"status":status,"journeyId":jid,"sequence":seq,"history":hist};if from!=""{m["fromLocationId"]=from};if to!=""{m["toLocationId"]=to};if node!=""{m["nodeId"]=node};if lab!=""{m["laboratoryId"]=lab};if expires.Valid{m["offerExpiresAt"]=expires.Time.UTC().Format(time.RFC3339Nano)};if node!=""||lab!=""{resource:=node;if resource==""{resource=lab};if cap,e:=a.capacity(ctx,resource);e==nil{m["destinationCapacity"]=cap}};out=append(out,m)};return out,rows.Err()}
func locationStale(t sql.NullTime)bool{return !t.Valid||time.Since(t.Time)>10*time.Minute}

func (a *App) timeline(ctx context.Context,entityType,entityID string)([]map[string]any,error){rows,e:=a.db.QueryContext(ctx,`SELECT id,action,actor_id,role,entity_type,entity_id,success,occurred_at,details FROM lablogistics.audit_log WHERE entity_type=$1 AND entity_id=$2 ORDER BY occurred_at,id`,entityType,entityID);if e!=nil{return nil,e};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id int;var action,actor,role,et,eid string;var success bool;var at time.Time;var raw []byte;if e=rows.Scan(&id,&action,&actor,&role,&et,&eid,&success,&at,&raw);e!=nil{return nil,e};var d map[string]any;_=json.Unmarshal(raw,&d);out=append(out,map[string]any{"eventId":id,"action":action,"actorId":actor,"role":role,"entityType":et,"entityId":eid,"success":success,"occurredAt":at.UTC().Format(time.RFC3339Nano),"details":d})};return out,rows.Err()}

func (a *App) canViewSample(ctx context.Context,u *User,sampleID string)error{if u.ActiveRole=="dispatcher"||u.ActiveRole=="administrator"{return nil};var n int;if u.ActiveRole=="requester"{e:=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogistics.samples WHERE id=$1 AND requester_id=$2`,sampleID,u.ID).Scan(&n);if e!=nil{return e}}else{e:=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogistics.assignments WHERE sample_id=$1 AND (offered_to=$2 OR worker_id=$2)`,sampleID,u.ID).Scan(&n);if e!=nil{return e}};if n==0{return fail(403,"forbidden","sample is outside selected role scope")};return nil}
func (a *App) readSampleState(w http.ResponseWriter,r *http.Request)error{u:=currentUser(r);if u.ActiveRole==""{return fail(409,"state_snapshot_changed","select an active role")};id:=strings.TrimPrefix(r.URL.Path,"/api/read-sample-state/");if e:=a.canViewSample(r.Context(),u,id);e!=nil{return e};m,e:=a.sampleState(r.Context(),id);if e!=nil{return e};writeJSON(w,200,map[string]any{"data":m});return nil}
func (a *App) sampleState(ctx context.Context,id string)(map[string]any,error){var requestID,requesterID,originType,requested,deadline,stype,container,svc,status,jid,lab string;var originRaw,latestRaw []byte;var min,max float64;var incompat,assignments []string;var loc sql.NullTime;e:=a.db.QueryRowContext(ctx,`SELECT request_id,coalesce(requester_id::text,''),origin,origin_type,requested_at::text,delivery_deadline::text,sample_type_id,container_type,temperature_min_c,temperature_max_c,incompatible_sample_types,serviceability,status,coalesce(active_journey_id::text,''),coalesce(target_laboratory_id::text,''),latest_location,location_recorded_at FROM lablogistics.samples WHERE id=$1`,id).Scan(&requestID,&requesterID,&originRaw,&originType,&requested,&deadline,&stype,&container,&min,&max,&incompat,&svc,&status,&jid,&lab,&latestRaw,&loc);if e==sql.ErrNoRows{return nil,fail(404,"not_found","sample not found")};if e!=nil{return nil,e};rows,e:=a.db.QueryContext(ctx,`SELECT id FROM lablogistics.assignments WHERE sample_id=$1 AND status NOT IN('completed','cancelled','declined')`,id);if e!=nil{return nil,e};for rows.Next(){var x string;_=rows.Scan(&x);assignments=append(assignments,x)};rows.Close();hist,e:=a.timeline(ctx,"sample",id);if e!=nil{return nil,e};var origin,latest any;_=json.Unmarshal(originRaw,&origin);_=json.Unmarshal(latestRaw,&latest);if incompat==nil{incompat=[]string{}};if assignments==nil{assignments=[]string{}};m:=map[string]any{"sampleId":id,"requestId":requestID,"requesterId":requesterID,"origin":origin,"originType":originType,"requestedAt":normalizePGTime(requested),"deliveryDeadline":normalizePGTime(deadline),"sampleTypeId":stype,"containerType":container,"temperatureMinC":min,"temperatureMaxC":max,"incompatibleSampleTypes":incompat,"serviceability":svc,"activeAssignmentIds":assignments,"state":map[string]any{"status":status},"timeline":hist,"locationStale":locationStale(loc)};if jid!=""{m["activeJourneyId"]=jid};if lab!=""{m["targetLaboratoryId"]=lab};if latest!=nil{m["latestLocation"]=latest};if loc.Valid{m["locationRecordedAt"]=loc.Time.UTC().Format(time.RFC3339Nano)};return m,nil}
func normalizePGTime(s string)string{t,e:=time.Parse("2006-01-02 15:04:05.999999999Z07:00",s);if e==nil{return t.UTC().Format(time.RFC3339Nano)};return s}
func (a *App) readSampleLifecycle(w http.ResponseWriter,r *http.Request)error{var in idRequest;if e:=decode(r,&in);e!=nil{return e};u:=currentUser(r);if e:=a.canViewSample(r.Context(),u,in.SampleID);e!=nil{return e};var status,holder,jid,lab string;var sealed bool;var excRaw []byte;e:=a.db.QueryRowContext(r.Context(),`SELECT status,sealed,coalesce(current_holder_id::text,''),coalesce(active_journey_id::text,''),coalesce(received_laboratory_id::text,''),exception FROM lablogistics.samples WHERE id=$1`,in.SampleID).Scan(&status,&sealed,&holder,&jid,&lab,&excRaw);if e==sql.ErrNoRows{return fail(404,"not_found","sample not found")};if e!=nil{return e};completed:=[]string{};rows,e:=a.db.QueryContext(r.Context(),`SELECT id FROM lablogistics.assignments WHERE sample_id=$1 AND status='completed'`,in.SampleID);if e!=nil{return e};for rows.Next(){var id string;_=rows.Scan(&id);completed=append(completed,id)};rows.Close();hist,_:=a.timeline(r.Context(),"sample",in.SampleID);m:=map[string]any{"sampleId":in.SampleID,"status":status,"sealed":sealed,"completedLegIds":completed,"activeReplacementPlanIds":[]string{},"timeline":hist,"locationStale":true};if holder!=""{m["currentHolderId"]=holder};if jid!=""{m["activeJourneyId"]=jid};if lab!=""{m["receivedLaboratoryId"]=lab};if len(excRaw)>0{var x any;_=json.Unmarshal(excRaw,&x);if x!=nil{m["exception"]=x}};var hid string;var sr,rr bool;var sender,receiver string;e=a.db.QueryRowContext(r.Context(),`SELECT id,sender_confirmed,receiver_confirmed,sender_id,receiver_id FROM lablogistics.handoffs WHERE sample_id=$1 AND status='pending'`,in.SampleID).Scan(&hid,&sr,&rr,&sender,&receiver);if e==nil{m["pendingHandoffId"]=hid;m["pendingHandoff"]=map[string]any{"handoffId":hid,"senderConfirmed":sr,"receiverConfirmed":rr,"senderId":sender,"receiverId":receiver}};writeJSON(w,200,map[string]any{"data":m});return nil}

func (a *App) readJourneyPlan(w http.ResponseWriter,r *http.Request)error{var in idRequest;if e:=decode(r,&in);e!=nil{return e};u:=currentUser(r);if u.ActiveRole==""{return fail(409,"role_not_selected","select an active role")};plan,e:=a.journeyPlan(r.Context(),in.JourneyID,u);if e!=nil{return e};writeJSON(w,200,map[string]any{"data":plan});return nil}
func (a *App) journeyPlan(ctx context.Context,id string,u *User)(map[string]any,error){var parent,mode,status string;var version,used int;var eta sql.NullTime;var cost float64;var samples []string;var stopsRaw []byte;e:=a.db.QueryRowContext(ctx,`SELECT coalesce(parent_journey_id::text,''),plan_version,route_mode,status,estimated_delivery_at,total_cost_units,capacity_used,sample_ids,ordered_stops FROM lablogistics.journeys WHERE id=$1`,id).Scan(&parent,&version,&mode,&status,&eta,&cost,&used,&samples,&stopsRaw);if e==sql.ErrNoRows{return nil,fail(404,"not_found","journey not found")};if e!=nil{return nil,e};if u.ActiveRole=="requester"{var n int;_=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogistics.samples WHERE active_journey_id=$1 AND requester_id=$2`,id,u.ID).Scan(&n);if n==0{return nil,fail(403,"forbidden","journey is outside requester scope")}}else if workerRole(u.ActiveRole){var n int;_=a.db.QueryRowContext(ctx,`SELECT count(*) FROM lablogistics.assignments WHERE journey_id=$1 AND (offered_to=$2 OR worker_id=$2)`,id,u.ID).Scan(&n);if n==0{return nil,fail(403,"forbidden","journey is outside worker scope")}}else if u.ActiveRole!="dispatcher"&&u.ActiveRole!="administrator"{return nil,fail(403,"forbidden","journey unavailable")};var stops []map[string]any;_=json.Unmarshal(stopsRaw,&stops);legs:=[]map[string]any{};assigned:=[]string{};collectionIDs,nodeIDs,labIDs:=[]string{},[]string{},[]string{};rows,e:=a.db.QueryContext(ctx,`SELECT id,sequence,status,coalesce(from_location_id::text,''),coalesce(to_location_id::text,''),coalesce(worker_id::text,''),kind FROM lablogistics.assignments WHERE journey_id=$1 ORDER BY sequence`,id);if e!=nil{return nil,e};for rows.Next(){var aid,st,from,to,worker,kind string;var seq int;if e=rows.Scan(&aid,&seq,&st,&from,&to,&worker,&kind);e!=nil{return nil,e};if workerRole(u.ActiveRole)&&worker!=u.ID{continue};leg:=map[string]any{"assignmentId":aid,"sequence":seq,"status":st};if from!=""{leg["fromLocationId"]=from};if to!=""{leg["toLocationId"]=to};if worker!=""{leg["workerId"]=worker;assigned=append(assigned,worker)};legs=append(legs,leg);if kind=="collection"{collectionIDs=append(collectionIDs,aid)};if kind=="node"{nodeIDs=append(nodeIDs,aid)};if kind=="laboratory"{labIDs=append(labIDs,aid)}};rows.Close();if u.ActiveRole=="requester"{redacted:=[]map[string]any{};for range legs{redacted=append(redacted,map[string]any{})};m:=map[string]any{"journeyId":id,"sampleIds":samples,"legs":redacted};if parent!=""{m["parentJourneyId"]=parent};m["planVersion"]=version;m["routeMode"]=mode;m["status"]=status;m["totalCostUnits"]=cost;m["orderedStops"]=stops;if eta.Valid{m["estimatedDeliveryAt"]=eta.Time.UTC().Format(time.RFC3339Nano)};return m,nil};if workerRole(u.ActiveRole){m:=map[string]any{"journeyId":id,"planVersion":version,"routeMode":mode,"status":status,"scope":"assigned_legs","assignmentIds":assignmentIDs(legs),"sampleIds":samples,"legs":legs,"orderedStops":stops,"collectionAssignmentIds":collectionIDs,"nodeAssignmentIds":nodeIDs,"laboratoryAssignmentIds":labIDs,"assignedWorkerIds":assigned};if parent!=""{m["parentJourneyId"]=parent};if eta.Valid{m["estimatedDeliveryAt"]=eta.Time.UTC().Format(time.RFC3339Nano)};return m,nil};m:=map[string]any{"journeyId":id,"planVersion":version,"routeMode":mode,"status":status,"totalCostUnits":cost,"capacityUsed":used,"capacityAvailable":0,"sampleIds":samples,"orderedStops":stops,"legs":legs,"assignedWorkerIds":assigned,"collectionAssignmentIds":collectionIDs,"nodeAssignmentIds":nodeIDs,"laboratoryAssignmentIds":labIDs,"valid":true};if parent!=""{m["parentJourneyId"]=parent};if eta.Valid{m["estimatedDeliveryAt"]=eta.Time.UTC().Format(time.RFC3339Nano)};return m,nil}
func assignmentIDs(legs []map[string]any)[]string{x:=[]string{};for _,l:=range legs{x=append(x,l["assignmentId"].(string))};return x}

func (a *App) readOperationsState(w http.ResponseWriter,r *http.Request)error{if _,e:=requireRole(r,"dispatcher","administrator");e!=nil{return e};var in struct{Filters map[string]any `json:"filters,omitempty"`};if e:=decode(r,&in);e!=nil{return e};ops,e:=a.operations(r.Context());if e!=nil{return e};writeJSON(w,200,map[string]any{"data":ops});return nil}
func (a *App) operations(ctx context.Context)(map[string]any,error){samples:=[]map[string]any{};rows,e:=a.db.QueryContext(ctx,`SELECT id,status,request_id,origin,delivery_deadline,coalesce(current_holder_id::text,''),coalesce(active_journey_id::text,''),latest_location,location_recorded_at FROM lablogistics.samples ORDER BY created_at DESC`);if e!=nil{return nil,e};for rows.Next(){var id,status,rid,holder,jid string;var originRaw,latestRaw []byte;var deadline time.Time;var loc sql.NullTime;if e=rows.Scan(&id,&status,&rid,&originRaw,&deadline,&holder,&jid,&latestRaw,&loc);e!=nil{return nil,e};var origin,latest any;_=json.Unmarshal(originRaw,&origin);_=json.Unmarshal(latestRaw,&latest);m:=map[string]any{"sampleId":id,"status":status,"requestId":rid,"origin":origin,"deliveryDeadline":deadline.UTC().Format(time.RFC3339Nano),"locationStale":locationStale(loc)};if holder!=""{m["currentHolderId"]=holder};if jid!=""{m["activeJourneyId"]=jid};if latest!=nil{m["latestLocation"]=latest};if loc.Valid{m["locationRecordedAt"]=loc.Time.UTC().Format(time.RFC3339Nano)};samples=append(samples,m)};rows.Close();workers:=[]map[string]any{};rows,e=a.db.QueryContext(ctx,`SELECT id,coalesce(full_name,username),roles,available,capacity_units,assignment_count FROM lablogistics.users WHERE roles&&ARRAY['collection_professional','delivery_partner']::text[]`);if e!=nil{return nil,e};for rows.Next(){var id,name string;var roles []string;var available bool;var cap,count int;if e=rows.Scan(&id,&name,&roles,&available,&cap,&count);e!=nil{return nil,e};workers=append(workers,map[string]any{"workerId":id,"fullName":name,"roles":roles,"available":available,"status":map[bool]string{true:"available",false:"unavailable"}[available],"capacityUnits":cap,"assignmentCount":count,"locationStale":true})};rows.Close();locations,e:=a.operationLocations(ctx);if e!=nil{return nil,e};connections,e:=a.operationConnections(ctx);if e!=nil{return nil,e};exceptions:=[]map[string]any{};for _,s:=range samples{if s["status