	res, e := a.db.ExecContext(r.Context(), `UPDATE lablogistics.locations SET capacity_units=$2,cooled_capacity_units=$3 WHERE id=$1 AND reserved_units<=$2 AND cooled_reserved_units<=$3`, in.ResourceID, in.CapacityUnits, in.CooledCapacityUnits)
