package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

type Certification struct {
	Code      string `json:"code"`
	Active    bool   `json:"active"`
	ExpiresAt string `json:"expiresAt,omitempty"`
}
type createUserRequest struct {
	Username           string          `json:"username"`
	InitialPassword    string          `json:"initialPassword"`
	Email              string          `json:"email,omitempty"`
	FullName           string          `json:"fullName,omitempty"`
	Phone              string          `json:"phone,omitempty"`
	Roles              []string        `json:"roles"`
	Qualifications     []string        `json:"qualifications,omitempty"`
	Certifications     []Certification `json:"certifications,omitempty"`
	Active             bool            `json:"active"`
	AssignedLocationID string          `json:"assignedLocationId,omitempty"`
}
type updateUserRequest struct {
	UserID             string          `json:"userId"`
	Roles              []string        `json:"roles"`
	Qualifications     []string        `json:"qualifications,omitempty"`
	Certifications     []Certification `json:"certifications,omitempty"`
	Active             bool            `json:"active"`
	AssignedLocationID string          `json:"assignedLocationId,omitempty"`
}

var validRoles = []string{"administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"}

func validRoleSet(rs []string) bool {
	if len(rs) == 0 {
		return false
	}
	for _, r := range rs {
		if !contains(validRoles, r) {
			return false
		}
	}
	return true
}
func validCerts(cs []Certification) bool {
	for _, c := range cs {
		if c.Code == "" {
			return false
		}
		if c.ExpiresAt != "" {
			if _, e := time.Parse(time.RFC3339, c.ExpiresAt); e != nil {
				return false
			}
		}
	}
	return true
}
func userResponse(id string, in createUserRequest) map[string]any {
	cs := in.Certifications
	if cs == nil {
		cs = []Certification{}
	}
	qs := in.Qualifications
	if qs == nil {
		qs = []string{}
	}
	m := map[string]any{"userId": id, "username": in.Username, "roles": in.Roles, "qualifications": qs, "certifications": cs, "active": in.Active}
	if in.Email != "" {
		m["email"] = in.Email
	}
	if in.FullName != "" {
		m["fullName"] = in.FullName
	}
	if in.Phone != "" {
		m["phone"] = in.Phone
	}
	return m
}
func (a *App) createUser(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "administrator")
	if e != nil {
		return e
	}
	var in createUserRequest
	if e = decode(r, &in); e != nil {
		return e
	}
	if in.Username == "" || len(in.InitialPassword) < 8 || !validRoleSet(in.Roles) {
		return fail(400, "invalid_user", "username, password, and valid roles are required")
	}
	if !validCerts(in.Certifications) {
		return fail(400, "invalid_certification", "invalid certification")
	}
	if (contains(in.Roles, "node_handler") || contains(in.Roles, "laboratory_team")) && in.AssignedLocationID == "" {
		return fail(400, "invalid_user", "assignedLocationId is required for facility roles")
	}
	h, _ := bcrypt.GenerateFromPassword([]byte(in.InitialPassword), bcrypt.DefaultCost)
	id := uuid()
	cert, _ := json.Marshal(in.Certifications)
	_, e = a.db.ExecContext(r.Context(), `INSERT INTO lablogistics.users(id,username,password_hash,email,full_name,phone,roles,qualifications,certifications,active,assigned_location_id) VALUES($1,$2,$3,NULLIF($4,''),NULLIF($5,''),NULLIF($6,''),$7,$8,$9,$10,NULLIF($11,'')::uuid)`, id, in.Username, string(h), in.Email, in.FullName, in.Phone, in.Roles, in.Qualifications, cert, in.Active, in.AssignedLocationID)
	if e != nil {
		if isUnique(e) {
			return fail(409, "username_exists", "username already exists")
		}
		return e
	}
	_ = a.audit(r.Context(), nil, u.ID, u.ActiveRole, "create_user", "user", id, true, map[string]any{"roles": in.Roles})
	writeJSON(w, 201, map[string]any{"data": userResponse(id, in)})
	return nil
}
func (a *App) updateUser(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "administrator")
	if e != nil {
		return e
	}
	var in updateUserRequest
	if e = decode(r, &in); e != nil {
		return e
	}
	if !validRoleSet(in.Roles) || !validCerts(in.Certifications) {
		return fail(400, "invalid_certification", "invalid role or certification")
	}
	cert, _ := json.Marshal(in.Certifications)
	res, e := a.db.ExecContext(r.Context(), `UPDATE lablogistics.users SET roles=$2,qualifications=$3,certifications=$4,active=$5,assigned_location_id=NULLIF($6,'')::uuid WHERE id=$1`, in.UserID, in.Roles, in.Qualifications, cert, in.Active, in.AssignedLocationID)
	if e != nil {
		return e
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return fail(404, "not_found", "user not found")
	}
	_ = a.audit(r.Context(), nil, u.ID, u.ActiveRole, "update_user_access", "user", in.UserID, true, map[string]any{"roles": in.Roles, "active": in.Active})
	qs := in.Qualifications
	if qs == nil {
		qs = []string{}
	}
	cs := in.Certifications
	if cs == nil {
		cs = []Certification{}
	}
	writeJSON(w, 201, map[string]any{"data": map[string]any{"userId": in.UserID, "roles": in.Roles, "qualifications": qs, "certifications": cs, "active": in.Active}})
	return nil
}
func (a *App) readUser(w http.ResponseWriter, r *http.Request) error {
	actor := currentUser(r)
	id := strings.TrimPrefix(r.URL.Path, "/api/read-user/")
	if actor.ID != id {
		if _, e := requireRole(r, "administrator"); e != nil {
			return e
		}
	}
	var out User
	var roles, quals []string
	var cert []byte
	var email, name, phone sql.NullString
	e := a.db.QueryRowContext(r.Context(), `SELECT id,username,email,full_name,phone,roles,qualifications,certifications,active FROM lablogistics.users WHERE id=$1`, id).Scan(&out.ID, &out.Username, &email, &name, &phone, &roles, &quals, &cert, &out.Active)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "user not found")
	}
	if e != nil {
		return e
	}
	var cs []Certification
	_ = json.Unmarshal(cert, &cs)
	if cs == nil {
		cs = []Certification{}
	}
	m := map[string]any{"userId": out.ID, "username": out.Username, "roles": roles, "qualifications": quals, "certifications": cs, "active": out.Active}
	if email.Valid {
		m["email"] = email.String
	}
	if name.Valid {
		m["fullName"] = name.String
	}
	if phone.Valid {
		m["phone"] = phone.String
	}
	writeJSON(w, 200, map[string]any{"data": m})
	return nil
}

type sampleTypeRequest struct {
	SampleTypeID               string   `json:"sampleTypeId,omitempty"`
	Name                       string   `json:"name,omitempty"`
	QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired,omitempty"`
	RequiredQualification      string   `json:"requiredQualification,omitempty"`
	ContainerType              string   `json:"containerType"`
