package main

import (
	"context"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

func (a *App) authenticate(w http.ResponseWriter, r *http.Request) {
	var in AuthRequest
	if err := decode(r, &in); err != nil {
		a.writeError(w, err)
		return
	}
	var u User
	var roles, quals []string
	var certRaw []byte
	err := a.db.QueryRowContext(r.Context(), `SELECT id,username,password_hash,coalesce(email,''),coalesce(full_name,''),coalesce(phone,''),roles,qualifications,certifications,active FROM lablogistics.users WHERE username=$1`, in.Username).Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &roles, &quals, &certRaw, &u.Active)
	if err != nil || !u.Active || bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(in.Password)) != nil {
		_ = a.audit(r.Context(), nil, "anonymous", "", "sign_in", "session", in.Username, false, map[string]any{"reason": "invalid_credentials"})
		a.writeError(w, fail(401, "invalid_credentials", "invalid username or password"))
		return
	}
	u.Roles = roles
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	sessionToken := token()
	_, err = a.db.ExecContext(r.Context(), `INSERT INTO lablogistics.sessions(token,user_id,active_role,expires_at) VALUES($1,$2,NULLIF($3,''),$4)`, sessionToken, u.ID, activeRole, time.Now().Add(24*time.Hour))
	if err != nil {
		a.writeError(w, err)
		return
	}
	_ = a.audit(r.Context(), nil, u.ID, activeRole, "sign_in", "session", sessionToken, true, map[string]any{})
	writeJSON(w, 200, map[string]any{"data": map[string]any{"sessionToken": sessionToken, "userId": u.ID, "roles": roles, "activeRole": activeRole}})
}

func (a *App) auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		t := strings.TrimSpace(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer "))
		if t == "" && r.URL.Path == "/api/events" {
			t = tokenFromSubprotocol(r.Header.Get("Sec-WebSocket-Protocol"))
		}
		if t == "" {
			a.writeError(w, fail(401, "unauthorized", "authentication required"))
			return
		}
		u, err := a.sessionUser(r.Context(), t)
		if err != nil {
			a.writeError(w, fail(401, "unauthorized", "invalid or expired session"))
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey, u)))
	})
}

func tokenFromSubprotocol(h string) string {
	for _, part := range strings.Split(h, ",") {
		p := strings.TrimSpace(part)
		if p == "lab-logistics-v1" {
			continue
		}
		if strings.HasPrefix(p, "bearer.") {
			raw := strings.TrimPrefix(p, "bearer.")
			if b, e := base64.RawURLEncoding.DecodeString(raw); e == nil {
				s := string(b)
				return strings.TrimPrefix(s, "bearer.")
			}
			return raw
		}
	}
	return ""
}

func (a *App) sessionUser(ctx context.Context, t string) (*User, error) {
	var u User
	var roles, quals []string
	var certRaw []byte
	var activeRole sql.NullString
	err := a.db.QueryRowContext(ctx, `SELECT u.id,u.username,coalesce(u.email,''),coalesce(u.full_name,''),coalesce(u.phone,''),u.roles,u.qualifications,u.certifications,u.active,coalesce(u.assigned_location_id::text,''),u.available,u.capacity_units,s.active_role FROM lablogistics.sessions s JOIN lablogistics.users u ON u.id=s.user_id WHERE s.token=$1 AND s.expires_at>now()`, t).Scan(&u.ID, &u.Username, &u.Email, &u.FullName, &u.Phone, &roles, &quals, &certRaw, &u.Active, &u.AssignedLocationID, &u.Available, &u.CapacityUnits, &activeRole)
	if err != nil || !u.Active {
		return nil, sql.ErrNoRows
	}
	u.Roles = roles
	u.Qualifications = quals
	u.ActiveRole = activeRole.String
	_ = json.Unmarshal(certRaw, &u.Certifications)
	if u.Certifications == nil {
		u.Certifications = []map[string]any{}
	}
	return &u, nil
}
func currentUser(r *http.Request) *User { return r.Context().Value(userKey).(*User) }
func requireRole(r *http.Request, allowed ...string) (*User, error) {
	u := currentUser(r)
	if u.ActiveRole == "" {
		return nil, fail(409, "role_not_selected", "select an active role")
	}
	if !contains(u.Roles, u.ActiveRole) {
		return nil, fail(403, "forbidden", "active role is not assigned")
	}
	for _, x := range allowed {
		if u.ActiveRole == x || (u.ActiveRole == "administrator" && x == "dispatcher") {
			return u, nil
		}
	}
	return nil, fail(403, "forbidden", "active role cannot perform this action")
}
func workerRole(role string) bool {
	return contains([]string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, role)
}

func (a *App) selectRole(w http.ResponseWriter, r *http.Request) error {
	var in roleRequest
	if err := decode(r, &in); err != nil {
		return err
	}
	u := currentUser(r)
	if !contains(u.Roles, in.Role) {
		return fail(403, "role_not_held", "role is not assigned to this account")
	}
	auth := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	if _, err := a.db.ExecContext(r.Context(), `UPDATE lablogistics.sessions SET active_role=$1 WHERE token=$2`, in.Role, auth); err != nil {
		return err
	}
	_ = a.audit(r.Context(), nil, u.ID, in.Role, "select_role", "user", u.ID, true, map[string]any{"role": in.Role})
	writeJSON(w, 200, map[string]any{"data": map[string]any{"activeRole": in.Role, "roles": u.Roles}})
	return nil
}

type execer interface {
	ExecContext(context.Context, string, ...any) (sql.Result, error)
}

func (a *App) audit(ctx context.Context, q execer, actor, role, action, entityType, entityID string, success bool, details map[string]any) error {
	if q == nil {
		q = a.db
	}
	b, _ := json.Marshal(details)
	id := uuid()
	_, err := q.ExecContext(ctx, `INSERT INTO lablogistics.audit_log(audit_id,actor_id,role,action,entity_type,entity_id,success,details) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`, id, actor, role, action, entityType, entityID, success, b)
	if err == nil && success {
		_, _ = q.ExecContext(ctx, `INSERT INTO lablogistics.events(type,entity_type,entity_id,audience_roles,payload) VALUES($1,$2,$3,$4,$5)`, action, entityType, entityID, []string{role, "dispatcher", "administrator"}, b)
	}
	return err
}

func (a *App) bootstrap(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	data := map[string]any{"user": map[string]any{"userId": u.ID, "username": u.Username, "roles": u.Roles, "activeRole": u.ActiveRole, "roleSelectionRequired": u.ActiveRole == ""}, "serverTime": now()}
	if u.FullName != "" {
		data["user"].(map[string]any)["fullName"] = u.FullName
	}
	if u.ActiveRole == "requester" {
		samples, err := a.requesterSamples(r.Context(), u.ID)
		if err != nil {
			return err
		}
		data["requesterSamples"] = samples
	}
	if u.ActiveRole == "dispatcher" || u.ActiveRole == "administrator" {
		ops, err := a.operations(r.Context())
		if err != nil {
			return err
		}
		data["operations"] = ops
	}
	writeJSON(w, 200, map[string]any{"data": data})
	return nil
}

func (a *App) events(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	since := int64(0)
	if s := r.URL.Query().Get("since"); s != "" {
		_, _ = fmt.Sscan(s, &since)
	}
	rows, err := a.db.QueryContext(r.Context(), `SELECT id,type,entity_type,entity_id,payload,created_at FROM lablogistics.events WHERE id>$1 AND ($2=ANY(audience_roles) OR 'administrator'=$2) ORDER BY id LIMIT 250`, since, u.ActiveRole)
	if err != nil {
		return err
	}
	defer rows.Close()
	out := []map[string]any{}
	cursor := since
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var raw []byte
		var at time.Time
		if err = rows.Scan(&id, &typ, &et, &eid, &raw, &at); err != nil {
			return err
		}
		var payload map[string]any
		_ = json.Unmarshal(raw, &payload)
		out = append(out, map[string]any{"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": payload, "createdAt": at.UTC().Format(time.RFC3339Nano)})
		cursor = id
	}
	writeJSON(w, 200, map[string]any{"data": map[string]any{"events": out, "cursor": cursor}})
	return rows.Err()
}

