	case r.Method == "GET" && r.URL.Path == "/api/events":
		err = a.events(w, r)
	case r.Method == "GET" && strings.HasPrefix(r.URL.Path, "/api/read-user/"):
		err = a.readUser(w, r)
	case r.Method == "GET" && strings.HasPrefix(r.URL.Path, "/api/read-sample-state/"):
		err = a.readSampleState(w, r)
	case r.Method == "POST":
		err = a.dispatchPost(w, r)
	default:
		err = fail(405, "method_not_allowed", "method not allowed")
	}
	if err != nil {
		a.writeError(w, err)
	}
}

func (a *App) dispatchPost(w http.ResponseWriter, r *http.Request) error {
	switch r.URL.Path {
	case "/api/check-serviceability":
		return a.checkServiceability(w, r)
	case "/api/create-collection-request":
		return a.createRequest(w, r, false)
	case "/api/ingest-presealed-sample":
		return a.createRequest(w, r, true)
	case "/api/create-user":
		return a.createUser(w, r)
	case "/api/read-user":
		return fail(404, "not_found", "not found")
	case "/api/update-user-access":
		return a.updateUser(w, r)
	case "/api/create-sample-type":
		return a.createSampleType(w, r, false)
	case "/api/update-sample-type":
		return a.createSampleType(w, r, true)
	case "/api/create-location":
		return a.createLocation(w, r, false)
	case "/api/update-location":
		return a.createLocation(w, r, true)
	case "/api/create-connection":
		return a.createConnection(w, r)
	case "/api/set-location-status":
		return a.setLocationStatus(w, r)
	case "/api/set-location-function-status":
		return a.setLocationFunctionStatus(w, r)
	case "/api/set-connection-status":
		return a.setConnectionStatus(w, r)
	case "/api/configure-capacity":
		return a.configureCapacity(w, r)
	case "/api/configure-laboratory-acceptance":
		return a.configureAcceptance(w, r)
	case "/api/set-worker-availability":
		return a.setWorkerAvailability(w, r)
	case "/api/list-role-work":
		return a.listRoleWork(w, r)
	case "/api/read-journey-plan":
		return a.readJourneyPlan(w, r)
	case "/api/read-sample-lifecycle":
		return a.readSampleLifecycle(w, r)
	case "/api/read-operations-state":
		return a.readOperationsState(w, r)
	case "/api/read-serviceability-snapshot":
		return a.readServiceabilitySnapshot(w, r)
	case "/api/search-audit-trail":
		return a.searchAudit(w, r)
	case "/api/accept-assignment":
		return a.acceptAssignment(w, r)
	case "/api/decline-assignment":
		return a.declineAssignment(w, r)
	case "/api/collect-and-seal-sample":
		return a.collectSample(w, r)
	case "/api/update-assignment-progress":
		return a.updateProgress(w, r)
	case "/api/record-worker-location":
		return a.recordLocation(w, r)
	case "/api/initiate-handoff":
		return a.initiateHandoff(w, r)
	case "/api/confirm-handoff":
		return a.confirmHandoff(w, r)
	case "/api/record-handling-checkpoint":
		return a.handlingCheckpoint(w, r)
	case "/api/confirm-laboratory-receipt":
		return a.labReceipt(w, r)
	case "/api/record-laboratory-exception":
		return a.labException(w, r)
	case "/api/edit-active-plan", "/api/reroute-journey", "/api/cancel-journey", "/api/split-journey", "/api/merge-journeys":
		return a.mutateJourney(w, r)
	case "/api/report-disruption":
		return a.reportDisruption(w, r)
	default:
		return fail(404, "not_found", "not found")
	}
}

func (a *App) cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "http://127.0.0.1:8080")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Sec-WebSocket-Protocol")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}
func (a *App) ready(w http.ResponseWriter, r *http.Request) {
	ctx, c := context.WithTimeout(r.Context(), 2*time.Second)
	defer c()
	if a.db.PingContext(ctx) != nil {
		writeJSON(w, 503, map[string]any{"status": "starting"})
		return
	}
	writeJSON(w, 200, map[string]any{"status": "ready"})
}
func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
func (a *App) writeError(w http.ResponseWriter, err error) {
	var ae *apiError
	if !errors.As(err, &ae) {
		log.Printf("internal error: %v", err)
		ae = fail(500, "internal_error", "internal server error")
	}
	writeJSON(w, ae.Status, map[string]any{"error": ae.Message, "code": ae.Code})
}
func decode(r *http.Request, v any) error {
	d := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	d.DisallowUnknownFields()
	if err := d.Decode(v); err != nil {
		return fail(400, "invalid_json", "invalid JSON request")
	}
	if d.Decode(&struct{}{}) != io.EOF {
		return fail(400, "invalid_json", "request must contain one JSON object")
	}
	return nil
}

func uuid() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}
func token() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return base64.RawURLEncoding.EncodeToString(b)
}
func hashJSON(v any) string {
	b, _ := json.Marshal(v)
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}
func pqArray(v []string) any { return v }
func now() string            { return time.Now().UTC().Format(time.RFC3339Nano) }
func contains(xs []string, x string) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}
func haversine(a, b Coordinate) float64 {
	const R = 6371.
	p1, p2 := a.Latitude*math.Pi/180, b.Latitude*math.Pi/180
	dp := (b.Latitude - a.Latitude) * math.Pi / 180
	dl := (b.Longitude - a.Longitude) * math.Pi / 180
	q := math.Sin(dp/2)*math.Sin(dp/2) + math.Cos(p1)*math.Cos(p2)*math.Sin(dl/2)*math.Sin(dl/2)
	return 2 * R * math.Atan2(math.Sqrt(q), math.Sqrt(1-q))
}

