			status = "exception"
		}
		_, e = tx.ExecContext(ctx, `INSERT INTO lablogistics.assignments(id,journey_id,sample_id,kind,required_role,offered_to,status,sequence,from_location_id,to_location_id,offer_expires_at)VALUES($1,$2,$3,'collection','collection_professional',NULLIF($4,'')::uuid,$5,$6,$7,$7,now()+interval '15 minutes')`, id, journeyID, sampleID, worker, status, sequence, rr.CollectionNodeID)
		if e != nil {
			return "", nil, e
		}
		ids = append(ids, id)
		sequence++
	}
	for i, x := range rr.Path {
		id := uuid()
		worker := a.chooseWorker(ctx, tx, "delivery_partner", "", "")
		status := "pending"
		if presealed && i == 0 {
			status = "offered"
		}
		_, e = tx.ExecContext(ctx, `INSERT INTO lablogistics.assignments(id,journey_id,sample_id,kind,required_role,offered_to,status,sequence,from_location_id,to_location_id,offer_expires_at)VALUES($1,$2,$3,'transport','delivery_partner',NULLIF($4,'')::uuid,$5,$6,$7,$8,now()+interval '15 minutes')`, id, journeyID, sampleID, worker, status, sequence, x.From, x.To)
		if e != nil {
			return "", nil, e
		}
		ids = append(ids, id)
		sequence++
	}
	id := uuid()
	worker := a.chooseWorker(ctx, tx, "laboratory_team", rr.LabID, "")
	_, e = tx.ExecContext(ctx, `INSERT INTO lablogistics.assignments(id,journey_id,sample_id,kind,required_role,offered_to,status,sequence,laboratory_id,node_id,offer_expires_at)VALUES($1,$2,$3,'laboratory','laboratory_team',NULLIF($4,'')::uuid,'pending',$5,$6,$6,now()+interval '15 minutes')`, id, journeyID, sampleID, worker, sequence, rr.LabID)
	if e != nil {
		return "", nil, e
	}
	ids = append(ids, id)
	for _, x := range rr.Path {
		col := "reserved_units"
		if rr.Rule.Cooled {
			col = "cooled_reserved_units"
		}
		q := `UPDATE lablogistics.connections SET ` + col + `=` + col + `+1 WHERE id=$1 AND ` + col + ` < ` + map[bool]string{true: "cooled_capacity_units", false: "capacity_units"}[rr.Rule.Cooled]
		res, xerr := tx.ExecContext(ctx, q, x.ID)
		if xerr != nil {
			return "", nil, xerr
		}
		n, _ := res.RowsAffected()
		if n == 0 {
			return "", nil, fail(409, map[bool]string{true: "cooled_capacity_exhausted", false: "capacity_exhausted"}[rr.Rule.Cooled], "capacity exhausted")
		}
		_, _ = tx.ExecContext(ctx, `INSERT INTO lablogistics.capacity_reservations(id,journey_id,resource_type,resource_id,cooled)VALUES($1,$2,'connection',$3,$4)`, uuid(), journeyID, x.ID, rr.Rule.Cooled)
	}
	return journeyID, ids, nil
}
func routeCost(xs []edge) float64 {
	n := 0.
	for _, x := range xs {
		n += x.Cost
	}
	return n
}
func (a *App) chooseWorker(ctx context.Context, tx *sql.Tx, role, location, qualification string) string {
	var id string
	q := `SELECT id FROM lablogistics.users WHERE active AND available AND $1=ANY(roles) AND ($2='' OR assigned_location_id=$2::uuid) AND ($3='' OR $3=ANY(qualifications)) ORDER BY decline_score,assignment_count,created_at LIMIT 1`
	if tx.QueryRowContext(ctx, q, role, location, qualification).Scan(&id) != nil {
		return ""
	}
	return id
}

func (a *App) readServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) error {
	if _, e := requireRole(r, "dispatcher", "administrator"); e != nil {
		return e
	}
	var empty struct{}
	if e := decode(r, &empty); e != nil {
		return e
	}
	var version, revision int
	var at time.Time
	e := a.db.QueryRowContext(r.Context(), `SELECT version,computed_at,network_revision FROM lablogistics.serviceability_snapshot WHERE singleton`).Scan(&version, &at, &revision)
	if e != nil {
		return e
	}
	rows, e := a.db.QueryContext(r.Context(), `SELECT id,name,latitude,longitude,coverage_km FROM lablogistics.locations WHERE active AND coalesce((functions->>'collection_point')::boolean,false)`)
	if e != nil {
		return e
	}
	defer rows.Close()
	regions := []map[string]any{}
	for rows.Next() {
		var id, name string
		var lat, lon, cov float64
		if e = rows.Scan(&id, &name, &lat, &lon, &cov); e != nil {
			return e
		}
		regions = append(regions, map[string]any{"locationId": id, "name": name, "latitude": lat, "longitude": lon, "coverageKm": cov})
	}
	writeJSON(w, 200, map[string]any{"data": map[string]any{"version": version, "status": "complete", "computedAt": at.UTC().Format(time.RFC3339Nano), "networkRevision": revision, "regions": regions, "activeCollectionPointCount": len(regions)}})
	return nil
}

func sortedKeys(m map[string]node) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

