	Cost                              float64
	Cooled                            bool
	RegularAvailable, CooledAvailable int
}
type sampleRule struct {
	Name, Container, Qualification string
	Min, Max                       float64
	Cooled, Qualified, Batching    bool
	Incompatible                   []string
}
type routeResult struct {
	Serviceable                     bool
	Reason, CollectionNodeID, LabID string
	Arrival                         time.Time
	Version                         int
	Path                            []edge
	Nodes                           map[string]node
	Rule                            sampleRule
}

func parseTime(s string) (time.Time, error) { return time.Parse(time.RFC3339, s) }
func (a *App) checkServiceability(w http.ResponseWriter, r *http.Request) error {
	if _, e := requireRole(r, "requester", "dispatcher", "administrator", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"); e != nil {
		return e
	}
	var in serviceRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	rr, e := a.serviceability(r.Context(), in)
	if e != nil {
		return e
	}
	data := map[string]any{"serviceable": rr.Serviceable, "reason": rr.Reason, "serviceabilityVersion": rr.Version}
