	at, e := parseTime(in.RecordedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid recordedAt")
	}
	if in.Sequence < 1 {
		return fail(400, "invalid_sequence", "sequence must be positive")
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var sid, worker string
	e = tx.QueryRowContext(r.Context(), `SELECT sample_id,coalesce(worker_id::text,offered_to::text,'') FROM lablogistics.assignments WHERE id=$1`, in.AssignmentID).Scan(&sid, &worker)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "assignment not found")
	}
	if e != nil {
		return e
	}
	if worker != u.ID {
		return fail(403, "forbidden", "assignment belongs to another worker")
	}
	raw, _ := json.Marshal(in.Coordinate)
	res, e := tx.ExecContext(r.Context(), `INSERT INTO lablogistics.worker_locations(assignment_id,worker_id,sequence,coordinate,recorded_at) VALUES($1,$2,$3,$4,$5) ON CONFLICT(assignment_id,sequence) DO NOTHING`, in.AssignmentID, u.ID, in.Sequence, raw, at)
	if e != nil {
		return e
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return fail(409, "stale_location", "location sequence is not newer")
	}
	_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.samples SET latest_location=$2,location_recorded_at=$3 WHERE id=$1 AND (location_recorded_at IS NULL OR location_recorded_at<$3)`, sid, raw, at)
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "record_worker_location", "sample", sid, true, map[string]any{"assignmentId": in.AssignmentID, "sequence": in.Sequence})
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, map[string]any{"data": map[string]any{"assignmentId": in.AssignmentID, "coordinate": in.Coordinate, "sequence": in.Sequence, "recordedAt": at.UTC().Format(time.RFC3339Nano)}})
	return nil
}

type initiateRequest struct {
	SampleID         string `json:"sampleId"`
	FromAssignmentID string `json:"fromAssignmentId"`
	ToAssignmentID   string `json:"toAssignmentId"`
	ReceiverID       string `json:"receiverId"`
	InitiatedAt      string `json:"initiatedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (a *App) initiateHandoff(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	if !workerRole(u.ActiveRole) {
		return fail(403, "forbidden", "worker role required")
	}
	var in initiateRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	at, e := parseTime(in.InitiatedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid initiatedAt")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "initiate_handoff", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var holder string
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(current_holder_id::text,'') FROM lablogistics.samples WHERE id=$1 FOR UPDATE`, in.SampleID).Scan(&holder)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "sample not found")
	}
	if holder != u.ID {
		return fail(409, "not_current_holder", "sender is not current holder")
	}
	var receiver string
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(worker_id::text,offered_to::text,'') FROM lablogistics.assignments WHERE id=$1 AND sample_id=$2`, in.ToAssignmentID, in.SampleID).Scan(&receiver)
	if e != nil {
		return fail(404, "not_found", "receiving assignment not found")
	}
	if receiver != in.ReceiverID {
		return fail(409, "receiver_assignment_mismatch", "receiver does not match assignment")
	}
	id := uuid()
	_, e = tx.ExecContext(r.Context(), `INSERT INTO lablogistics.handoffs(id,sample_id,from_assignment_id,to_assignment_id,sender_id,receiver_id,initiated_at)VALUES($1,$2,$3,$4,$5,$6,$7)`, id, in.SampleID, in.FromAssignmentID, in.ToAssignmentID, u.ID, in.ReceiverID, at)
	if e != nil {
		return fail(409, "pending_handoff_exists", "a handoff is already pending")
	}
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "initiate_handoff", "sample", in.SampleID, true, map[string]any{"handoffId": id, "receiverId": in.ReceiverID})
	out := map[string]any{"data": map[string]any{"handoffId": id, "senderId": u.ID, "receiverId": in.ReceiverID, "currentHolderId": u.ID, "status": "pending"}}
	_ = a.saveIdempotency(r.Context(), tx, u, "initiate_handoff", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}

type confirmRequest struct {
