	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "confirm_handoff", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var sample, sender, receiver, status string
	var sc, rc bool
	e = tx.QueryRowContext(r.Context(), `SELECT sample_id,sender_id,receiver_id,sender_confirmed,receiver_confirmed,status FROM lablogistics.handoffs WHERE id=$1 FOR UPDATE`, in.HandoffID).Scan(&sample, &sender, &receiver, &sc, &rc, &status)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "handoff not found")
	}
	if status != "pending" {
		return fail(409, "handoff_inactive", "handoff is complete")
	}
	if (in.ConfirmationSide == "sender" && u.ID != sender) || (in.ConfirmationSide == "receiver" && u.ID != receiver) {
		return fail(403, "forbidden", "only the named handoff party may confirm")
	}
	if in.ConfirmationSide == "sender" {
		sc = true
	} else {
		rc = true
	}
	current := sender
	newStatus := "pending"
	if sc && rc {
		newStatus = "confirmed"
		current = receiver
		_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.samples SET current_holder_id=$2 WHERE id=$1 AND current_holder_id=$3`, sample, receiver, sender)
		if e != nil {
			return e
		}
	}
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.handoffs SET sender_confirmed=$2,receiver_confirmed=$3,status=$4,completed_at=CASE WHEN $4='confirmed' THEN $5 ELSE NULL END WHERE id=$1`, in.HandoffID, sc, rc, newStatus, at)
	if e != nil {
		return e
	}
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "confirm_handoff", "sample", sample, true, map[string]any{"handoffId": in.HandoffID, "side": in.ConfirmationSide, "status": newStatus})
	out := map[string]any{"data": map[string]any{"handoffId": in.HandoffID, "status": newStatus, "senderConfirmed": sc, "receiverConfirmed": rc, "currentHolderId": current}}
	_ = a.saveIdempotency(r.Context(), tx, u, "confirm_handoff", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}

type checkpointRequest struct {
