}

func (a *App) handlingCheckpoint(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	if !workerRole(u.ActiveRole) {
		return fail(403, "forbidden", "worker role required")
	}
	var in checkpointRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	at, e := parseTime(in.RecordedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid recordedAt")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "handling_checkpoint", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var holder, status, container string
	var min, max float64
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(current_holder_id::text,''),status,container_type,temperature_min_c,temperature_max_c FROM lablogistics.samples WHERE id=$1 FOR UPDATE`, in.SampleID).Scan(&holder, &status, &container, &min, &max)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "sample not found")
	}
	if holder != u.ID {
		return fail(403, "forbidden", "only the current holder can record a checkpoint")
	}
	compliant := container == in.ContainerType && in.ObservedTemperatureC >= min && in.ObservedTemperatureC <= max
	id := uuid()
	_, e = tx.ExecContext(r.Context(), `INSERT INTO lablogistics.handling_checkpoints(id,sample_id,assignment_id,location_id,container_type,observed_temperature_c,compliant,recorded_at)VALUES($1,$2,$3,NULLIF($4,'')::uuid,$5,$6,$7,$8)`, id, in.SampleID, in.AssignmentID, in.LocationID, in.ContainerType, in.ObservedTemperatureC, compliant, at)
	if e != nil {
		return e
	}
	if !compliant {
		status = "exception"
		exc, _ := json.Marshal(map[string]any{"reason": "handling_noncompliant", "checkpointId": id, "observedAt": in.RecordedAt})
		_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.samples SET status='exception',exception=$2 WHERE id=$1`, in.SampleID, exc)
	}
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "record_handling_checkpoint", "sample", in.SampleID, true, map[string]any{"checkpointId": id, "compliant": compliant})
	out := map[string]any{"data": map[string]any{"checkpointId": id, "sampleId": in.SampleID, "compliant": compliant, "sampleStatus": status}}
	_ = a.saveIdempotency(r.Context(), tx, u, "handling_checkpoint", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}

