func (a *App) labReceipt(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "laboratory_team")
	if e != nil {
		return e
	}
	var in receiptRequest
	if e = decode(r, &in); e != nil {
		return e
	}
	at, e := parseTime(in.ReceivedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid receivedAt")
	}
	if u.AssignedLocationID != in.LaboratoryID {
		return fail(403, "wrong_laboratory_operator", "operator is assigned to another laboratory")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "lab_receipt", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var holder, target, jid string
	var deadline time.Time
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(current_holder_id::text,''),coalesce(target_laboratory_id::text,''),coalesce(active_journey_id::text,''),delivery_deadline FROM lablogistics.samples WHERE id=$1 FOR UPDATE`, in.SampleID).Scan(&holder, &target, &jid, &deadline)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "sample not found")
	}
	if target != in.LaboratoryID {
		return fail(409, "receipt_not_ready", "sample is not expected at this laboratory")
	}
	if holder != u.ID {
		return fail(409, "custody_conflict", "laboratory operator does not hold sample")
	}
	if at.After(deadline) {
		return fail(409, "delivery_deadline_exceeded", "delivery deadline exceeded")
	}
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.samples SET status='received',received_laboratory_id=$2 WHERE id=$1`, in.SampleID, in.LaboratoryID)
	if e != nil {
		return e
	}
	_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.assignments SET status='completed',progress_at=$2 WHERE sample_id=$1 AND kind='laboratory'`, in.SampleID, at)
	_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.journeys SET status='completed',active=false WHERE id=$1`, jid)
	_ = a.releaseCapacity(r.Context(), tx, jid)
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "confirm_laboratory_receipt", "sample", in.SampleID, true, map[string]any{"laboratoryId": in.LaboratoryID})
	out := map[string]any{"data": map[string]any{"sampleId": in.SampleID, "laboratoryId": in.LaboratoryID, "status": "received", "receivedAt": at.UTC().Format(time.RFC3339Nano)}}
	_ = a.saveIdempotency(r.Context(), tx, u, "lab_receipt", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
