	exc := map[string]any{"exceptionId": id, "reason": in.Reason, "observedAt": in.ObservedAt, "laboratoryId": in.LaboratoryID}
	raw, _ := json.Marshal(exc)
	res, e := a.db.ExecContext(r.Context(), `UPDATE lablogistics.samples SET status='exception',exception=$2 WHERE id=$1`, in.SampleID, raw)
	if e != nil {
		return e
	}
	n, _ := res.RowsAffected()
	if n == 0 {
