package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"net/http"
	"time"
)

type assignmentIDRequest struct {
	AssignmentID   string `json:"assignmentId"`
	IdempotencyKey string `json:"idempotencyKey"`
}
type declineRequest struct {
	AssignmentID   string `json:"assignmentId"`
	Reason         string `json:"reason,omitempty"`
	DeclinedAt     string `json:"declinedAt,omitempty"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func requireKey(k string) error {
	if k == "" {
		return fail(400, "idempotency_required", "idempotencyKey is required")
	}
	return nil
}
func (a *App) priorIdempotency(ctx context.Context, u *User, op, key string, in any) (map[string]any, int, error) {
	if e := requireKey(key); e != nil {
		return nil, 0, e
	}
	var hash string
	var status int
	var raw []byte
	e := a.db.QueryRowContext(ctx, `SELECT request_hash,status_code,response FROM lablogistics.idempotency WHERE actor_id=$1 AND operation=$2 AND key=$3`, u.ID, op, key).Scan(&hash, &status, &raw)
	if e == sql.ErrNoRows {
		return nil, 0, nil
	}
	if e != nil {
		return nil, 0, e
	}
	if hash != hashJSON(in) {
		return nil, 0, fail(409, "idempotency_conflict", "idempotency key was used with another request")
	}
	var out map[string]any
	_ = json.Unmarshal(raw, &out)
	return out, status, nil
}
func (a *App) saveIdempotency(ctx context.Context, q execer, u *User, op, key string, in, out any, status int) error {
	b, _ := json.Marshal(out)
	_, e := q.ExecContext(ctx, `INSERT INTO lablogistics.idempotency(actor_id,operation,key,request_hash,status_code,response)VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`, u.ID, op, key, hashJSON(in), status, b)
	return e
}
func assignmentRoleOK(role, required string) bool { return role == required }

func (a *App) acceptAssignment(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	if u.ActiveRole == "" {
		return fail(409, "role_not_selected", "select an active role")
	}
	var in assignmentIDRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "accept_assignment", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var offered, required, status string
	var expires sql.NullTime
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(offered_to::text,''),required_role,status,offer_expires_at FROM lablogistics.assignments WHERE id=$1 FOR UPDATE`, in.AssignmentID).Scan(&offered, &required, &status, &expires)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "assignment not found")
	}
	if e != nil {
		return e
	}
	if !assignmentRoleOK(u.ActiveRole, required) {
		return fail(403, "ineligible_worker", "selected role is not eligible")
	}
	if offered != u.ID {
		return fail(409, "offer_not_offered", "assignment was not offered to this worker")
	}
	if status != "offered" {
		return fail(409, "assignment_taken", "assignment is no longer offered")
	}
	if expires.Valid && time.Now().After(expires.Time) {
		return fail(409, "offer_not_available", "assignment offer expired")
	}
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.assignments SET worker_id=$2,status='accepted' WHERE id=$1`, in.AssignmentID, u.ID)
	if e != nil {
		return e
	}
	_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.users SET assignment_count=assignment_count+1 WHERE id=$1`, u.ID)
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "accept_assignment", "assignment", in.AssignmentID, true, map[string]any{})
	out := map[string]any{"data": map[string]any{"assignmentId": in.AssignmentID, "workerId": u.ID, "status": "accepted"}}
	_ = a.saveIdempotency(r.Context(), tx, u, "accept_assignment", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}
func (a *App) declineAssignment(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	if u.ActiveRole == "" {
		return fail(409, "role_not_selected", "select an active role")
	}
	var in declineRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	if in.DeclinedAt == "" {
		in.DeclinedAt = now()
	} else if _, e := parseTime(in.DeclinedAt); e != nil {
		return fail(400, "invalid_time", "invalid declinedAt")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "decline_assignment", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var offered, required, status, location string
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(offered_to::text,''),required_role,status,coalesce(node_id::text,laboratory_id::text,'') FROM lablogistics.assignments WHERE id=$1 FOR UPDATE`, in.AssignmentID).Scan(&offered, &required, &status, &location)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "assignment not found")
	}
	if e != nil {
		return e
	}
	if offered != u.ID || status != "offered" {
		return fail(409, "offer_not_available", "offer is not available")
	}
	_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.users SET decline_score=least(decline_score+1,10) WHERE id=$1`, u.ID)
	next := a.chooseWorkerExcluding(r.Context(), tx, required, location, "", u.ID)
	newStatus := "pending"
	if next != "" {
		newStatus = "offered"
	}
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.assignments SET offered_to=NULLIF($2,'')::uuid,worker_id=NULL,status=$3,offer_expires_at=now()+interval '15 minutes' WHERE id=$1`, in.AssignmentID, next, newStatus)
	if e != nil {
		return e
	}
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "decline_assignment", "assignment", in.AssignmentID, true, map[string]any{"reason": in.Reason, "reofferedTo": next})
	data := map[string]any{"assignmentId": in.AssignmentID, "status": "pending", "declinedBy": u.ID, "declinedAt": in.DeclinedAt}
	if next != "" {
		data["reofferedTo"] = next
	}
	out := map[string]any{"data": data}
	_ = a.saveIdempotency(r.Context(), tx, u, "decline_assignment", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}
func (a *App) chooseWorkerExcluding(ctx context.Context, tx *sql.Tx, role, location, qualification, excluded string) string {
	var id string
