type collectRequest struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	CollectedAt          string  `json:"collectedAt"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (a *App) collectSample(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "collection_professional")
	if e != nil {
		return e
	}
	var in collectRequest
	if e = decode(r, &in); e != nil {
		return e
	}
	collected, e := parseTime(in.CollectedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid collectedAt")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "collect_sample", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var status, worker string
	var earliest, latest time.Time
	var container string
	var min, max float64
	e = tx.QueryRowContext(r.Context(), `SELECT a.status,coalesce(a.worker_id::text,''),s.earliest_collection_at,s.latest_collection_at,s.container_type,s.temperature_min_c,s.temperature_max_c FROM lablogistics.assignments a JOIN lablogistics.samples s ON s.id=a.sample_id WHERE a.id=$1 AND a.sample_id=$2 AND a.kind='collection' FOR UPDATE OF a,s`, in.AssignmentID, in.SampleID).Scan(&status, &worker, &earliest, &latest, &container, &min, &max)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "collection assignment not found")
	}
	if e != nil {
		return e
	}
	if worker != u.ID {
		return fail(403, "forbidden", "assignment belongs to another worker")
	}
	if status != "accepted" {
		return fail(409, "assignment_inactive", "assignment must be accepted")
	}
	if collected.Before(earliest) || collected.After(latest) {
		return fail(409, "outside_collection_window", "collection time is outside the collection window")
	}
	compliant := container == in.ContainerType && in.ObservedTemperatureC >= min && in.ObservedTemperatureC <= max
	newStatus := "sealed"
	var exception any = nil
	if !compliant {
		newStatus = "exception"
		exception = map[string]any{"reason": "handling_noncompliant", "observedAt": in.CollectedAt}
	}
	exc, _ := json.Marshal(exception)
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.samples SET status=$2,sealed=true,current_holder_id=$3,exception=$4 WHERE id=$1`, in.SampleID, newStatus, u.ID, exc)
	if e != nil {
		return e
	}
	_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.assignments SET status='completed',progress_at=$2 WHERE id=$1`, in.AssignmentID, collected)
	_ = a.activateNext(r.Context(), tx, in.SampleID)
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "collect_and_seal", "sample", in.SampleID, true, map[string]any{"assignmentId": in.AssignmentID, "handlingCompliant": compliant})
	out := map[string]any{"data": map[string]any{"sampleId": in.SampleID, "status": "sealed", "currentHolderId": u.ID, "sealedAt": collected.UTC().Format(time.RFC3339Nano), "handlingCompliant": compliant}}
	_ = a.saveIdempotency(r.Context(), tx, u, "collect_sample", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}
func (a *App) activateNext(ctx context.Context, tx *sql.Tx, sampleID string) error {
	_, e := tx.ExecContext(ctx, `UPDATE lablogistics.assignments SET status=CASE WHEN offered_to IS NULL THEN 'exception' ELSE 'offered' END,offer_expires_at=now()+interval '15 minutes' WHERE id=(SELECT id FROM lablogistics.assignments WHERE sample_id=$1 AND status='pending' ORDER BY sequence LIMIT 1)`, sampleID)
	return e
}

