}

func (a *App) updateProgress(w http.ResponseWriter, r *http.Request) error {
	u := currentUser(r)
	if !contains([]string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, u.ActiveRole) {
		return fail(403, "forbidden", "worker role required")
	}
	var in progressRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	at, e := parseTime(in.OccurredAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid occurredAt")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "update_progress", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var sid, worker, status string
	e = tx.QueryRowContext(r.Context(), `SELECT sample_id,coalesce(worker_id::text,''),status FROM lablogistics.assignments WHERE id=$1 FOR UPDATE`, in.AssignmentID).Scan(&sid, &worker, &status)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "assignment not found")
	}
	if e != nil {
		return e
	}
	if worker != u.ID {
		return fail(403, "forbidden", "assignment belongs to another worker")
	}
	if !contains([]string{"accepted", "at_pickup", "picked_up", "in_transit", "arrived", "delivered", "in_progress"}, status) {
		return fail(409, "assignment_inactive", "assignment is inactive")
	}
	next := in.Status
	if in.Status == "completed" || in.Status == "delivered" {
		next = "completed"
	}
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.assignments SET status=$2,progress_at=$3 WHERE id=$1`, in.AssignmentID, next, at)
	if e != nil {
		return e
	}
	if next == "completed" {
		_ = a.activateNext(r.Context(), tx, sid)
	}
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "update_assignment_progress", "assignment", in.AssignmentID, true, map[string]any{"status": in.Status, "sampleId": sid})
	out := map[string]any{"data": map[string]any{"assignmentId": in.AssignmentID, "sampleId": sid, "status": in.Status}}
	_ = a.saveIdempotency(r.Context(), tx, u, "update_progress", in.IdempotencyKey, in, out, 201)
	if e = tx.Commit(); e != nil {
		return e
	}
	writeJSON(w, 201, out)
	return nil
}

