	}
	var in locationRecordRequest
	if e := decode(r, &in); e != nil {
		return e
	}
	if !validCoordinate(in.Coordinate) {
		return fail(400, "invalid_coordinate", "invalid coordinate")
	}
	at, e := parseTime(in.RecordedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid recordedAt")
	}
	if in.Sequence < 1 {
		return fail(400, "invalid_sequence", "sequence must be positive")
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var sid, worker string
	e = tx.QueryRowContext(r.Context(), `SELECT sample_id,coalesce(worker_id::text,offered_to::text,'') FROM lablogistics.assignments WHERE id=$1`, in.AssignmentID).Scan(&sid, &worker)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "assignment not found")
	}
	if e != nil {
		return e
	}
	if worker != u.ID {
		return fail(403, "forbidden", "assignment belongs to another worker")
	}
	raw, _ := json.Marshal(in.Coordinate)
	res, e := tx.ExecContext(r.Context(), `INSERT INTO lablogistics.worker_locations(assignment_id,worker_id,sequence,coordinate,recorded_at) VALUES($1,$2,$3,$4,$5) ON CONFLICT(assignment_id,sequence) DO NOTHING`, in.AssignmentID, u.ID, in.Sequence, raw, at)
