	if e := decode(r, &in); e != nil {
		return e
	}
	at, e := parseTime(in.InitiatedAt)
	if e != nil {
		return fail(400, "invalid_time", "invalid initiatedAt")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "initiate_handoff", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
