	if e != nil {
		return e
	}
	defer tx.Rollback()
	var holder string
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(current_holder_id::text,'') FROM lablogistics.samples WHERE id=$1 FOR UPDATE`, in.SampleID).Scan(&holder)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "sample not found")
	}
	if holder != u.ID {
		return fail(409, "not_current_holder", "sender is not current holder")
	}
	var receiver string
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(worker_id::text,offered_to::text,'') FROM lablogistics.assignments WHERE id=$1 AND sample_id=$2`, in.ToAssignmentID, in.SampleID).Scan(&receiver)
