		writeJSON(w, status, out)
		return nil
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var holder, status, container string
	var min, max float64
	e = tx.QueryRowContext(r.Context(), `SELECT coalesce(current_holder_id::text,''),status,container_type,temperature_min_c,temperature_max_c FROM lablogistics.samples WHERE id=$1 FOR UPDATE`, in.SampleID).Scan(&holder, &status, &container, &min, &max)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "sample not found")
