func (a *App) labException(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "laboratory_team")
	if e != nil {
		return e
	}
	var in labExceptionRequest
	if e = decode(r, &in); e != nil {
		return e
	}
	if _, e = parseTime(in.ObservedAt); e != nil {
		return fail(400, "invalid_time", "invalid observedAt")
