	if u.AssignedLocationID != in.LaboratoryID {
		return fail(403, "wrong_laboratory_operator", "operator is assigned to another laboratory")
	}
	if out, status, e := a.priorIdempotency(r.Context(), u, "lab_exception", in.IdempotencyKey, in); e != nil {
		return e
	} else if out != nil {
		writeJSON(w, status, out)
		return nil
	}
	id := uuid()
	exc := map[string]any{"exceptionId": id, "reason": in.Reason, "observedAt": in.ObservedAt, "laboratoryId": in.LaboratoryID}
