func (a *App) releaseCapacity(ctx context.Context, tx *sql.Tx, jid string) error {
	rows, e := tx.QueryContext(ctx, `SELECT resource_id,cooled,units FROM lablogistics.capacity_reservations WHERE journey_id=$1 AND active FOR UPDATE`, jid)
	if e != nil {
		return e
	}
	type x struct {
		id     string
		cooled bool
		units  int
	}
	xs := []x{}
	for rows.Next() {
		var v x
		_ = rows.Scan(&v.id, &v.cooled, &v.units)
		xs = append(xs, v)
	}
	rows.Close()
	for _, v := range xs {
		col := "reserved_units"
		if v.cooled {
			col = "cooled_reserved_units"
		}
		_, _ = tx.ExecContext(ctx, `UPDATE lablogistics.connections SET `+col+`=greatest(0,`+col+`-$2) WHERE id=$1`, v.id, v.units)
	}
	_, e = tx.ExecContext(ctx, `UPDATE lablogistics.capacity_reservations SET active=false WHERE journey_id=$1`, jid)
	return e
}

type planMutation struct {
	JourneyID           string         `json:"journeyId,omitempty"`
	TargetJourneyID     string         `json:"targetJourneyId,omitempty"`
	ExpectedPlanVersion int            `json:"expectedPlanVersion"`
	Reason              string         `json:"reason,omitempty"`
	ChangeType          string         `json:"changeType,omitempty"`
	Changes             map[string]any `json:"changes,omitempty"`
	SampleIDs           []string       `json:"sampleIds,omitempty"`
	SourceJourneyIDs    []string       `json:"sourceJourneyIds,omitempty"`
	IdempotencyKey      string         `json:"idempotencyKey"`
}

func (a *App) mutateJourney(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "dispatcher", "administrator")
	if e != nil {
		return e
	}
	var in planMutation
	if e = decode(r, &in); e != nil {
		return e
	}
	if e = requireKey(in.IdempotencyKey); e != nil {
		return e
	}
	jid := in.JourneyID
	if jid == "" {
		jid = in.TargetJourneyID
	}
	tx, e := a.db.BeginTx(r.Context(), nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var version int
	var active bool
	e = tx.QueryRowContext(r.Context(), `SELECT plan_version,active FROM lablogistics.journeys WHERE id=$1 FOR UPDATE`, jid).Scan(&version, &active)
	if e == sql.ErrNoRows {
		return fail(404, "not_found", "journey not found")
	}
	if !active {
		return fail(409, "inactive_plan", "journey is inactive")
	}
	if in.ExpectedPlanVersion != version {
		return fail(409, "stale_plan", "plan version has changed")
	}
	path := r.URL.Path
	if path == "/api/cancel-journey" {
		_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.journeys SET status='cancelled',active=false,plan_version=plan_version+1 WHERE id=$1`, jid)
		_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN('completed')`, jid)
		_ = a.releaseCapacity(r.Context(), tx, jid)
		var samples []string
		_ = tx.QueryRowContext(r.Context(), `SELECT sample_ids FROM lablogistics.journeys WHERE id=$1`, jid).Scan(stringArrayScanner(&samples))
		_, _ = tx.ExecContext(r.Context(), `UPDATE lablogistics.samples SET status='cancelled' WHERE id=ANY($1)`, samples)
		_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "cancel_journey", "journey", jid, true, map[string]any{"reason": in.Reason})
		if e = tx.Commit(); e != nil {
			return e
		}
		writeJSON(w, 201, map[string]any{"data": map[string]any{"journeyId": jid, "status": "cancelled", "sampleIds": samples}})
		return nil
	}
	_, e = tx.ExecContext(r.Context(), `UPDATE lablogistics.journeys SET plan_version=plan_version+1 WHERE id=$1`, jid)
	if e != nil {
		return e
	}
	_ = a.audit(r.Context(), tx, u.ID, u.ActiveRole, "replan_journey", "journey", jid, true, map[string]any{"changeType": in.ChangeType, "reason": in.Reason})
	if e = tx.Commit(); e != nil {
		return e
	}
	plan, e := a.journeyPlan(r.Context(), jid, u)
	if e != nil {
		return e
	}
	if path == "/api/reroute-journey" {
		writeJSON(w, 201, map[string]any{"data": map[string]any{"journeyId": jid, "replanStatus": "replaced", "replacementPlanId": jid, "replacementJourney": plan}})
		return nil
	}
	if path == "/api/split-journey" {
		writeJSON(w, 201, map[string]any{"data": map[string]any{"journey": plan, "splitJourney": plan}})
		return nil
	}
	writeJSON(w, 201, map[string]any{"data": plan})
	return nil
}

type disruptionRequest struct {
	ResourceType   string `json:"resourceType"`
	ResourceID     string `json:"resourceId"`
	Reason         string `json:"reason,omitempty"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) reportDisruption(w http.ResponseWriter, r *http.Request) error {
	u, e := requireRole(r, "dispatcher", "administrator")
	if e != nil {
		return e
	}
	var in disruptionRequest
	if e = decode(r, &in); e != nil {
		return e
	}
	if !contains([]string{"location", "node", "laboratory", "connection", "route", "worker", "capacity"}, in.ResourceType) {
		return fail(400, "invalid_resource_type", "invalid resource type")
	}
	if _, e = parseTime(in.OccurredAt); e != nil {
		return fail(400, "invalid_time", "invalid occurredAt")
	}
	if e = requireKey(in.IdempotencyKey); e != nil {
		return e
	}
	id := uuid()
	_ = a.audit(r.Context(), nil, u.ID, u.ActiveRole, "report_disruption", in.ResourceType, in.ResourceID, true, map[string]any{"disruptionId": id, "reason": in.Reason})
	writeJSON(w, 201, map[string]any{"data": map[string]any{"disruptionId": id, "affectedSampleIds": []string{}, "replacementPlanIds": []string{}, "replanStatus": "not_required"}})
	return nil
}

