function Shell({token,data,refresh,logout,toast,setToast}:{token:string,data:Data,refresh:()=>void,logout:()=>void,toast:string,setToast:(s:string)=>void}){
  const role=data.user.activeRole;const [view,setView]=useState('overview');const [mobile,setMobile]=useState(false);const [switching,setSwitching]=useState(false);
  const nav=role==='administrator'?[['overview','Overview',LayoutDashboard],['network','Network',Network],['users','Users & access',Users],['audit','Audit trail',History]]:role==='dispatcher'?[['overview','Live operations',LayoutDashboard],['journeys','Journeys',Route],['audit','Audit trail',History]]:role==='requester'?[['overview','My samples',FlaskConical],['new','New collection',Plus]]:[['overview','My work',ClipboardList],['history','Completed work',History]];
  const selectRole=async(r:string)=>{await api('/select-active-role',{role:r},token);setSwitching(false);await refresh()};
  return <div className="app-shell"><aside className={mobile?'open':''}><div className="wordmark inverse"><span><FlaskConical/></span>LABLINK<button className="mobile-close" onClick={()=>setMobile(false)}><X/></button></div><div className="role-chip">{roleIcons[role]}<span><small>WORKING AS</small>{roleNames[role]}</span></div><nav>{nav.map(([id,label,Icon]:any)=><button key={id} className={view===id?'active':''} onClick={()=>{setView(id);setMobile(false)}}><Icon/>{label}</button>)}</nav><div className="side-bottom"><button onClick={()=>setSwitching(true)}><RefreshCw/>Switch role</button><button onClick={logout}><LogOut/>Sign out</button></div></aside><main className="workspace"><header className="topbar"><button className="menu-button" onClick={()=>setMobile(true)}><Menu/></button><div className="searchbox"><Search/><input aria-label="Search" placeholder="Search samples, journeys or locations…"/></div><div className="top-actions"><span className="live-dot">LIVE</span><button className="avatar">{(data.user.fullName||data.user.username||'U').slice(0,2).toUpperCase()}</button></div></header><div className="content">{role==='requester'?<Requester token={token} initial={data.requesterSamples||[]} view={view} refreshBootstrap={refresh} notify={setToast}/>:role==='administrator'?<Admin token={token} initial={data.operations} view={view} notify={setToast}/>:role==='dispatcher'?<Dispatcher token={token} initial={data.operations} view={view} notify={setToast}/>:<Worker token={token} role={role} history={view==='history'} notify={setToast}/>}</div></main>{switching&&<Modal title="Switch role" onClose={()=>setSwitching(false)}><div className="switch-list">{data.user.roles.map((r:string)=><button key={r} disabled={r===role} onClick={()=>selectRole(r)}>{roleIcons[r]}<span><b>{roleNames[r]}</b><small>{r===role?'Current workspace':roleDescriptions[r]}</small></span><ChevronRight/></button>)}</div></Modal>}{toast&&<div className="toast"><CheckCircle2/>{toast}<button onClick={()=>setToast('')}><X/></button></div>}</div>
}

function Header({eyebrow,title,description,action}:{eyebrow:string,title:string,description:string,action?:React.ReactNode}){return <div className="page-header"><div><span className="eyebrow dark">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function Stat({icon,value,label,detail,tone='navy'}:{icon:React.ReactNode,value:any,label:string,detail:string,tone?:string}){return <article className="stat-card"><span className={`stat-icon ${tone}`}>{icon}</span><div><small>{label}</small><strong>{value}</strong><p>{detail}</p></div></article>}
function Empty({icon=<Box/>,title,text}:{icon?:React.ReactNode,title:string,text:string}){return <div className="empty">{icon}<h3>{title}</h3><p>{text}</p></div>}

function Requester({token,initial,view,refreshBootstrap,notify}:{token:string,initial:Data[],view:string,refreshBootstrap:()=>void,notify:(s:string)=>void}){
 const [samples,setSamples]=useState(initial);const [selected,setSelected]=useState<Data|null>(initial[0]||null);const [details,setDetails]=useState<Data|null>(null);
 useEffect(()=>setSamples(initial),[initial]);useEffect(()=>{if(selected?.sampleId)Promise.all([api(`/read-sample-state/${selected.sampleId}`,undefined,token,'GET'),api('/read-sample-lifecycle',{sampleId:selected.sampleId},token)]).then(([state,lifecycle])=>setDetails({...state,...lifecycle,state:state.state})).catch(()=>{})},[selected?.sampleId]);
 if(view==='new')return <NewRequest token={token} done={async()=>{notify('Collection request created');await refreshBootstrap()}}/>;
 const active=samples.filter(s=>!['received','cancelled','expired'].includes(s.status));const complete=samples.length-active.length;
 return <><Header eyebrow="REQUESTER WORKSPACE" title="My samples" description="Track every collection from request to laboratory receipt." action={<button className="primary" onClick={()=>location.hash='new'}><Plus/>New collection</button>}/><div className="stat-grid three"><Stat icon={<FlaskConical/>} value={active.length} label="ACTIVE SAMPLES" detail="Moving through the network"/><Stat icon={<Clock3/>} value={active.filter(s=>s.locationStale).length} label="AWAITING UPDATE" detail="Last location needs refresh" tone="amber"/><Stat icon={<CheckCircle2/>} value={complete} label="DELIVERED" detail="Successfully received" tone="green"/></div><section className="split-layout"><div className="panel"><div className="panel-title"><div><h2>Recent requests</h2><p>Current and completed collections</p></div><button className="icon-button" onClick={refreshBootstrap}><RefreshCw/></button></div>{samples.length===0?<Empty title="No sample requests yet" text="Create your first collection to begin tracking."/>:<div className="sample-list">{samples.map(s=><button key={s.sampleId} className={selected?.sampleId===s.sampleId?'selected':''} onClick={()=>setSelected(s)}><span className={`sample-orb ${sampleTone(s)}`}><FlaskConical/></span><span className="sample-main"><b>{s.sampleId.slice(0,8).toUpperCase()}</b><small>{shortDate(s.requestedAt)} · Due {shortDate(s.deliveryDeadline)}</small></span><Status value={s.status}/><ChevronRight/></button>)}</div>}</div><div className="panel detail-panel">{selected?<SampleDetail sample={details||selected}/>:<Empty icon={<Route/>} title="Select a sample" text="Choose a request to view route and custody history."/>}</div></section></>
}
function sampleTone(s:Data){return s.status==='received'?'green':s.locationStale?'amber':'indigo'}
function Status({value}:{value:string}){return <span className={`status status-${value}`}>{value==='in_transit'&&<span className="pulse"/>}{statusLabel(value)}</span>}
function SampleDetail({sample}:{sample:Data}){const timeline=sample.timeline||sample.history||[];const state=sample.state?.status||sample.status;return <><div className="detail-head"><div><span className="eyebrow dark">SAMPLE</span><h2>{sample.sampleId?.slice(0,8).toUpperCase()}</h2></div><Status value={state}/></div>{sample.exception&&<div className="form-error"><AlertTriangle/><span><b>Sample exception</b><br/>{statusLabel(String(sample.exception.reason||sample.exception.type||sample.exception.code||'Handling requirements not met'))}</span></div>}<div className="route-progress"><div className="route-line"><i className="done"/><i className={state==='sealed'||state==='in_transit'||state==='received'?'done':''}/><i className={state==='received'?'done':''}/></div><div><span><b>Collected</b><small>{shortDate(sample.requestedAt)}</small></span><span><b>In transit</b><small>{sample.locationStale?'Update pending':'Location current'}</small></span><span><b>Laboratory</b><small>{state==='received'?'Received':'Due '+shortDate(sample.deliveryDeadline)}</small></span></div></div><div className="info-grid"><span><small>CURRENT CUSTODIAN</small><b>{sample.currentHolderId?.slice(0,8)||'Not yet assigned'}</b></span><span><small>JOURNEY</small><b>{sample.activeJourneyId?.slice(0,8)||'Planning'}</b></span><span><small>LAST LOCATION</small><b>{sample.latestLocation?`${Number(sample.latestLocation.latitude).toFixed(3)}, ${Number(sample.latestLocation.longitude).toFixed(3)}`:'Origin'}</b></span><span><small>FRESHNESS</small><b className={sample.locationStale?'warn':'ok'}>{sample.locationStale?'Location stale':'Up to date'}</b></span></div><h3 className="section-label">Status timeline</h3><div className="timeline">{timeline.length?timeline.slice().reverse().slice(0,8).map((t:Data,i:number)=><div key={t.eventId||i}><i className={i===0?'latest':''}/><span><b>{statusLabel(t.action)}</b><small>{shortDate(t.occurredAt)} · {roleNames[t.role]||t.role}</small></span></div>):<p className="muted">Lifecycle updates will appear here.</p>}</div></>}

function NewRequest({token,done}:{token:string,done:()=>void}){const [type,setType]=useState(sampleTypes[0]);const [originType,setOriginType]=useState('home');const [lat,setLat]=useState('12.9716');const [lon,setLon]=useState('77.5946');const [earliest,setEarliest]=useState(isoAfter(30).slice(0,16));const [latest,setLatest]=useState(isoAfter(120).slice(0,16));const [deadline,setDeadline]=useState(isoAfter(360).slice(0,16));const [check,setCheck]=useState<Data|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 const base=()=>({origin:{latitude:Number(lat),longitude:Number(lon)},originType,sampleTypeId:type.id,requestedAt:new Date().toISOString(),earliestCollectionAt:new Date(earliest).toISOString(),latestCollectionAt:new Date(latest).toISOString(),deliveryDeadline:new Date(deadline).toISOString()});
 const service=async()=>{setBusy(true);setError('');try{setCheck(await api('/check-serviceability',base(),token))}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const create=async()=>{setBusy(true);try{const temp=type.name==='Frost'?{containerType:'Cooled transport carrier',temperatureMinC:2,temperatureMaxC:8}:{containerType:'Sealed clinical transport container',temperatureMinC:15,temperatureMaxC:25};await api('/create-collection-request',{...base(),...temp,incompatibleSampleTypes:type.name==='Indigo'?['10000000-0000-4000-8000-000000000001']:[],idempotencyKey:uid()},token);done();setCheck(null)}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 return <><Header eyebrow="NEW COLLECTION" title="Request a sample pickup" description="Check network coverage and deadline feasibility before confirming."/><div className="form-layout"><section className="panel form-panel"><div className="step-title"><b>1</b><span><h2>Sample & origin</h2><p>Tell us what needs collecting and where.</p></span></div><label>Collection origin<div className="segmented"><button className={originType==='home'?'active':''} onClick={()=>setOriginType('home')}>Patient home</button><button className={originType==='clinic'?'active':''} onClick={()=>setOriginType('clinic')}>Clinic</button></div></label><label>Sample type<div className="type-grid">{sampleTypes.map(s=><button key={s.id} className={`${s.tone} ${type.id===s.id?'active':''}`} onClick={()=>{setType(s);setCheck(null)}}><FlaskConical/><span><b>{s.name}</b><small>{s.note}</small></span></button>)}</div></label><div className="field-row"><label>Latitude<input value={lat} onChange={e=>setLat(e.target.value)} type="number" step="any"/></label><label>Longitude<input value={lon} onChange={e=>setLon(e.target.value)} type="number" step="any"/></label></div><div className="step-title"><b>2</b><span><h2>Collection timing</h2><p>Pickup window and laboratory deadline.</p></span></div><div className="field-row"><label>Earliest pickup<input value={earliest} onChange={e=>setEarliest(e.target.value)} type="datetime-local"/></label><label>Latest pickup<input value={latest} onChange={e=>setLatest(e.target.value)} type="datetime-local"/></label></div><label>Delivery deadline<input value={deadline} onChange={e=>setDeadline(e.target.value)} type="datetime-local"/></label>{error&&<div className="form-error"><AlertTriangle/>{error}</div>}<button className="secondary wide" disabled={busy} onClick={service}><Route/>{busy?'Checking network…':'Check serviceability'}</button></section><aside>{check?<div className={`service-card ${check.serviceable?'available':'unavailable'}`}><span>{check.serviceable?<CheckCircle2/>:<AlertTriangle/>}</span><h2>{check.serviceable?'Collection available':'Not serviceable'}</h2><p>{check.serviceable?'A route and accepting laboratory are available before your deadline.':statusLabel(check.reason)}</p><dl><div><dt>Network version</dt><dd>v{check.serviceabilityVersion}</dd></div><div><dt>Estimated arrival</dt><dd>{shortDate(check.estimatedArrivalAt)}</dd></div><div><dt>Target laboratory</dt><dd>{check.targetLaboratoryId?.slice(0,8)||'—'}</dd></div></dl>{check.serviceable&&<button className="primary wide" disabled={busy} onClick={create}>Confirm collection<ArrowRight/></button>}<small className="dry-run"><ShieldCheck/>No capacity is reserved until you confirm.</small></div>:<div className="service-placeholder"><MapIcon/><h3>Serviceability check</h3><p>Complete the details and check the network for coverage, capacity and deadline feasibility.</p></div>}</aside></div></>
}

function Worker({token,role,history,notify}:{token:string,role:string,history:boolean,notify:(s:string)=>void}){const [work,setWork]=useState<Data>({pending:[],inProgress:[],completed:[]});const [busy,setBusy]=useState('');const [modal,setModal]=useState<Data|null>(null);const load=()=>api('/list-role-work',{role},token).then(setWork);useEffect(()=>{load()},[role]);const items=history?work.completed:[...work.pending,...work.inProgress];const act=async(path:string,body:Data,msg:string)=>{setBusy(body.assignmentId||'x');try{await api(path,{...body,idempotencyKey:uid()},token);notify(msg);setModal(null);await load()}catch(e){notify((e as Error).message)}finally{setBusy('')}};
 return <><Header eyebrow={`${roleNames[role].toUpperCase()} WORKSPACE`} title={history?'Completed work':'My work'} description={history?'Review assignments and their status history.':'Offers and active assignments requiring your attention.'} action={<button className="secondary" onClick={load}><RefreshCw/>Refresh</button>}/><div className="stat-grid three"><Stat icon={<ClipboardList/>} value={work.pending.length} label="NEW OFFERS" detail="Waiting for your response" tone="amber"/><Stat icon={<Truck/>} value={work.inProgress.length} label="IN PROGRESS" detail="Accepted and active"/><Stat icon={<CheckCircle2/>} value={work.completed.length} label="COMPLETED" detail="Past assignments" tone="green"/></div><section className="panel"><div className="panel-title"><div><h2>{history?'Assignment history':'Assignment queue'}</h2><p>{items.length} item{items.length===1?'':'s'} in this view</p></div></div>{items.length===0?<Empty icon={<ClipboardList/>} title={history?'No completed work':'Your queue is clear'} text={history?'Completed assignments will appear here.':'New offers will appear automatically when assigned.'}/>:<div className="work-grid">{items.map((x:Data)=><article key={x.assignmentId||x.sampleId} className="work-card"><div className="work-top"><span className="kind-icon">{x.kind==='collection'?<PackageCheck/>:x.kind==='laboratory'?<Building2/>:<Truck/>}</span><div><small>{statusLabel(x.kind)} · LEG {Number(x.sequence||0)+1}</small><h3>{x.sampleId?.slice(0,8).toUpperCase()}</h3></div><Status value={x.status}/></div><div className="leg"><span><i/><small>FROM</small><b>{x.fromLocationId?.slice(0,8)||'Collection origin'}</b></span><ArrowRight/><span><i/><small>TO</small><b>{(x.toLocationId||x.laboratoryId)?.slice(0,8)||'Next facility'}</b></span></div>{role==='laboratory_team'&&x.destinationCapacity&&<div className="capacity-summary"><small>LABORATORY CAPACITY</small><b>{x.destinationCapacity.availableUnits} regular · {x.destinationCapacity.cooledAvailableUnits} cooled available</b></div>}{x.offerExpiresAt&&<p className="expires"><Clock3/>Respond by {shortDate(x.offerExpiresAt)}</p>}<div className="work-actions">{x.status==='offered'&&<><button className="primary" disabled={!!busy} onClick={()=>act('/accept-assignment',{assignmentId:x.assignmentId},'Assignment accepted')}><CheckCircle2/>Accept</button><button className="danger-soft" disabled={!!busy} onClick={()=>act('/decline-assignment',{assignmentId:x.assignmentId,reason:'Unavailable',declinedAt:new Date().toISOString()},'Assignment declined')}>Decline</button></>}{x.status==='accepted'&&<><button className="primary" onClick={()=>setModal(x)}>{x.kind==='collection'?'Collect & seal':'Update progress'}</button>{['collection_professional','delivery_partner'].includes(role)&&<button className="secondary" onClick={()=>act('/record-worker-location',{assignmentId:x.assignmentId,coordinate:{latitude:12.9716,longitude:77.5946},sequence:Date.now()%1000000,recordedAt:new Date().toISOString()},'Location recorded')}><MapIcon/>Location</button>}</>}</div></article>)}</div>}</section>{modal&&<ActionModal item={modal} role={role} close={()=>setModal(null)} act={act}/>}</>
}
function ActionModal({item,role,close,act}:{item:Data,role:string,close:()=>void,act:(p:string,b:Data,m:string)=>void}){const [temp,setTemp]=useState('22');const [container,setContainer]=useState('Sealed clinical transport container');const [progress,setProgress]=useState('in_transit');return <Modal title={item.kind==='collection'?'Collect and seal sample':'Update assignment'} onClose={close}>{item.kind==='collection'?<><div className="modal-sample"><FlaskConical/><span><small>SAMPLE</small><b>{item.sampleId.slice(0,8).toUpperCase()}</b></span></div><label>Container observed<select value={container} onChange={e=>setContainer(e.target.value)}><option>Sealed clinical transport container</option><option>Cooled transport carrier</option></select></label><label>Observed temperature (°C)<input value={temp} onChange={e=>setTemp(e.target.value)} type="number" step="0.1"/></label><div className="callout"><ShieldCheck/>By confirming, you attest that collection and sealing were completed within the approved window.</div><button className="primary wide" onClick={()=>act('/collect-and-seal-sample',{sampleId:item.sampleId,assignmentId:item.assignmentId,collectedAt:new Date().toISOString(),containerType:container,observedTemperatureC:Number(temp)},'Sample collected and sealed')}><PackageCheck/>Confirm collection</button></>:<><label>Progress status<select value={progress} onChange={e=>setProgress(e.target.value)}><option value="at_pickup">At pickup</option><option value="picked_up">Picked up</option><option value="in_transit">In transit</option><option value="arrived">Arrived</option><option value="completed">Completed</option></select></label><button className="primary wide" onClick={()=>act('/update-assignment-progress',{assignmentId:item.assignmentId,status:progress,occurredAt:new Date().toISOString()},'Progress updated')}>Save progress</button>{role==='laboratory_team'&&<button className="secondary wide">Record receipt instead</button>}</>}</Modal>}

function Dispatcher({token,initial,view,notify}:{token:string,initial:Data,view:string,notify:(s:string)=>void}){const [ops,setOps]=useState(initial||{});const [selected,setSelected]=useState<Data|null>(null);const load=()=>api('/read-operations-state',{},token).then(setOps);useEffect(()=>{const t=setInterval(load,30000);return()=>clearInterval(t)},[]);if(view==='audit')return <Audit token={token}/>;if(view==='journeys')return <JourneyView token={token} notify={notify}/>;const active=(ops.samples||[]).filter((s:Data)=>!['received','cancelled'].includes(s.status));return <><Header eyebrow="NETWORK CONTROL" title="Live operations" description="A real-time view of samples, workers, capacity and exceptions." action={<button className="secondary" onClick={load}><RefreshCw/>Refresh data</button>}/><div className="stat-grid four"><Stat icon={<FlaskConical/>} value={active.length} label="ACTIVE SAMPLES" detail="Across the network"/><Stat icon={<Truck/>} value={(ops.workers||[]).filter((w:Data)=>w.available).length} label="AVAILABLE WORKERS" detail={`${(ops.workers||[]).length} total field workers`} tone="green"/><Stat icon={<Warehouse/>} value={(ops.locations||[]).length} label="ACTIVE LOCATIONS" detail="Collection points and labs"/><Stat icon={<AlertTriangle/>} value={(ops.exceptions||[]).length} label="EXCEPTIONS" detail="Require dispatcher review" tone="rose"/></div><section className="map-panel panel"><div className="panel-title"><div><h2>Network live map</h2><p>Current sample positions and active facilities</p></div><div className="map-legend"><span><i className="sample"/>Samples</span><span><i className="facility"/>Facilities</span></div></div><NetworkMap samples={ops.samples||[]} locations={ops.locations||[]} onSelect={setSelected}/></section><section className="panel"><div className="panel-title"><div><h2>Samples in motion</h2><p>Custody, freshness and deadline overview</p></div><span className="count-pill">{active.length} ACTIVE</span></div><div className="table-wrap"><table><thead><tr><th>Sample</th><th>Status</th><th>Current custodian</th><th>Last location</th><th>Delivery deadline</th><th>Freshness</th><th></th></tr></thead><tbody>{active.map((s:Data)=><tr key={s.sampleId}><td><b>{s.sampleId.slice(0,8).toUpperCase()}</b><small>{s.requestId.slice(0,8)}</small></td><td><Status value={s.status}/></td><td>{s.currentHolderId?.slice(0,8)||'Awaiting holder'}</td><td>{s.latestLocation?`${s.latestLocation.latitude.toFixed(3)}, ${s.latestLocation.longitude.toFixed(3)}`:'Origin'}</td><td>{shortDate(s.deliveryDeadline)}</td><td><span className={s.locationStale?'freshness stale':'freshness'}>{s.locationStale?'STALE':'CURRENT'}</span></td><td><button className="icon-button" onClick={()=>setSelected(s)}><ChevronRight/></button></td></tr>)}</tbody></table></div></section>{selected&&<Drawer title={`Sample ${selected.sampleId.slice(0,8).toUpperCase()}`} close={()=>setSelected(null)}><SampleDetail sample={selected}/><div className="drawer-actions"><button className="secondary"><Route/>Open journey</button><button className="danger-soft"><AlertTriangle/>Report disruption</button></div></Drawer>}</>
}

function NetworkMap({samples,locations,onSelect}:{samples:Data[],locations:Data[],onSelect:(x:Data)=>void}){const ref=useRef<HTMLDivElement>(null);const mapRef=useRef<MLMap|null>(null);useEffect(()=>{if(!ref.current||mapRef.current)return;const protocol=new Protocol();maplibregl.addProtocol('pmtiles',protocol.tile);const map=new maplibregl.Map({container:ref.current,center:[77.5946,12.9716],zoom:10.5,attributionControl:false,style:{version:8,sources:{local:{type:'vector',url:'pmtiles:///map/bangalore.pmtiles'}},layers:[{id:'bg',type:'background',paint:{'background-color':'#e9eef3'}},{id:'roads',type:'line',source:'local','source-layer':'transportation',paint:{'line-color':'#c5d0dc','line-width':1.2}},{id:'water',type:'fill',source:'local','source-layer':'water',paint:{'fill-color':'#b9dded'}},{id:'buildings',type:'fill',source:'local','source-layer':'building',paint:{'fill-color':'#dae2e9','fill-opacity':.7}}]}});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'bottom-right');mapRef.current=map;return()=>{map.remove();mapRef.current=null}},[]);useEffect(()=>{const map=mapRef.current;if(!map)return;const marks:(maplibregl.Marker)[]=[];locations.forEach(l=>{if(!l.coordinate)return;const el=document.createElement('button');el.className='map-marker facility-marker';el.innerHTML='<span>+</span>';el.title=l.name;marks.push(new maplibregl.Marker({element:el}).setLngLat([l.coordinate.longitude,l.coordinate.latitude]).addTo(map))});samples.forEach(s=>{const p=s.latestLocation||s.origin;if(!p)return;const el=document.createElement('button');el.className='map-marker sample-marker';el.innerHTML='<span></span>';el.onclick=()=>onSelect(s);marks.push(new maplibregl.Marker({element:el}).setLngLat([p.longitude,p.latitude]).addTo(map))});return()=>marks.forEach(m=>m.remove())},[samples,locations]);return <div ref={ref} className="network-map"/>}

function JourneyView({token,notify}:{token:string,notify:(s:string)=>void}){const [id,setId]=useState('');const [plan,setPlan]=useState<Data|null>(null);const read=async()=>{try{setPlan(await api('/read-journey-plan',{journeyId:id},token))}catch(e){notify((e as Error).message)}};return <><Header eyebrow="JOURNEY CONTROL" title="Journey plans" description="Inspect versioned routes and manage unfinished work."/><section className="panel search-panel"><input placeholder="Enter journey ID" value={id} onChange={e=>setId(e.target.value)}/><button className="primary" onClick={read}><Search/>Find journey</button></section>{plan?<section className="panel journey-plan"><div className="panel-title"><div><h2>Journey {plan.journeyId.slice(0,8)}</h2><p>Plan version {plan.planVersion} · {statusLabel(plan.routeMode)}</p></div><Status value={plan.status}/></div><div className="stop-list">{(plan.orderedStops||[]).map((s:Data,i:number)=><div key={s.stopId}><i>{i+1}</i><span><b>{statusLabel(s.stopType)}</b><small>{s.locationId.slice(0,8)} · {shortDate(s.estimatedAt)}</small></span></div>)}</div><div className="drawer-actions"><button className="secondary"><Route/>Reroute</button><button className="danger-soft"><X/>Cancel journey</button></div></section>:<Empty icon={<Route/>} title="Find a journey" text="Search by journey ID to inspect its active plan."/>}</>}

function Admin({token,initial,view,notify}:{token:string,initial:Data,view:string,notify:(s:string)=>void}){if(view==='audit')return <Audit token={token}/>;if(view==='users')return <UserAdmin token={token} notify={notify}/>;if(view==='network')return <NetworkAdmin token={token} initial={initial} notify={notify}/>;return <Dispatcher token={token} initial={initial} view="overview" notify={notify}/>}
function UserAdmin({token,notify}:{token:string,notify:(s:string)=>void}){const [open,setOpen]=useState(false);const [username,setUsername]=useState('');const [name,setName]=useState('');const [password,setPassword]=useState('ChangeMe123!');const [role,setRole]=useState('requester');const create=async()=>{try{await api('/create-user',{username,initialPassword:password,fullName:name,roles:[role],qualifications:[],certifications:[],active:true},token);notify('User account created');setOpen(false)}catch(e){notify((e as Error).message)}};return <><Header eyebrow="ADMINISTRATION" title="Users & access" description="Manage role assignments, certifications and facility access." action={<button className="primary" onClick={()=>setOpen(true)}><Plus/>Add user</button>}/><div className="stat-grid three"><Stat icon={<Users/>} value="—" label="ACTIVE USERS" detail="Across all workspaces"/><Stat icon={<ShieldCheck/>} value="7" label="SYSTEM ROLES" detail="Least-privilege access"/><Stat icon={<Building2/>} value="—" label="FACILITY STAFF" detail="Node and laboratory teams"/></div><section className="panel"><div className="panel-title"><div><h2>User directory</h2><p>Use Add user to onboard an account under a specific role.</p></div></div><Empty icon={<UserCog/>} title="Search the user directory" text="Account details remain protected until you open a known user record."/></section>{open&&<Modal title="Add user" onClose={()=>setOpen(false)}><label>Full name<input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Asha Raman"/></label><label>Username<input value={username} onChange={e=>setUsername(e.target.value)} placeholder="e.g. asha.r"/></label><label>Initial password<input type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label><label>Role<select value={role} onChange={e=>setRole(e.target.value)}>{Object.entries(roleNames).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label><button className="primary wide" onClick={create}>Create user</button></Modal>}</>}
function NetworkAdmin({token,initial,notify}:{token:string,initial:Data,notify:(s:string)=>void}){const [ops,setOps]=useState(initial||{});const toggle=async(l:Data)=>{try{await api('/set-location-status',{locationId:l.locationId,active:!l.active},token);notify(`${l.name} ${l.active?'deactivated':'activated'}`);setOps(await api('/read-operations-state',{},token))}catch(e){notify((e as Error).message)}};return <><Header eyebrow="NETWORK CONFIGURATION" title="Locations & connections" description="Configure facilities, functions, capabilities and live status." action={<button className="primary"><Plus/>Add location</button>}/><section className="panel"><div className="panel-title"><div><h2>Network locations</h2><p>Changes are applied without restarting the application.</p></div></div><div className="location-grid">{(ops.locations||[]).map((l:Data)=><article key={l.id}><div><span className="location-icon">{l.functions?.laboratory?<Building2/>:<Warehouse/>}</span><Status value={l.active?'active':'inactive'}/></div><h3>{l.name}</h3><p>{Object.entries(l.functions||{}).filter(([,v])=>v).map(([k])=>statusLabel(k)).join(' · ')||'No functions enabled'}</p><div className="capacity-bar"><span style={{width:`${Math.min(100,(l.capacity.reservedUnits/Math.max(l.capacity.capacityUnits,1))*100)}%`}}/></div><small>{l.capacity.availableUnits} of {l.capacity.capacityUnits} regular units available</small><button className="secondary wide" onClick={()=>toggle(l)}>{l.active?'Deactivate':'Activate'}</button></article>)}</div></section></>}

function Audit({token}:{token:string}){const [query,setQuery]=useState('');const [entries,setEntries]=useState<Data[]>([]);const [loading,setLoading]=useState(false);const search=async()=>{setLoading(true);try{const d=await api('/search-audit-trail',{query,limit:100,offset:0,order:'newest_first'},token);setEntries(d.entries)}finally{setLoading(false)}};useEffect(()=>{search()},[]);return <><Header eyebrow="COMPLIANCE" title="Audit trail" description="Search immutable operational and access history."/><section className="panel audit-panel"><div className="audit-search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} placeholder="Search actions, entities or details"/><button className="primary" onClick={search}>Search</button></div><div className="audit-list">{loading?<div className="spinner"/>:entries.map(e=><article key={e.auditId}><i/><div><b>{statusLabel(e.action)}</b><p>{e.entityType} · {e.entityId.slice(0,12)}</p></div><span><b>{roleNames[e.role]||e.role||'System'}</b><small>{shortDate(e.occurredAt)}</small></span></article>)}</div></section></>}

function Modal({title,onClose,children}:{title:string,onClose:()=>void,children:React.ReactNode}){return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal"><header><h2>{title}</h2><button onClick={onClose}><X/></button></header><div className="modal-body">{children}</div></section></div>}
function Drawer({title,close,children}:{title:string,close:()=>void,children:React.ReactNode}){return <div className="drawer-backdrop" onClick={e=>e.target===e.currentTarget&&close()}><aside className="drawer"><header><h2>{title}</h2><button onClick={close}><X/></button></header><div>{children}</div></aside></div>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);

